-- 0001_initial.sql == schema.sql at v1 (the baseline). Generated; see migrations/README.md.
-- schema.sql — the results registry DDL (GENERATED by sisteer.registry.schema_def; do not edit by hand).
-- Regenerate with `registry docs schema` (which also rewrites docs/registry/schema.md).
-- Every CHECK (col IN (...)) list is rendered from vocab.py; the object.fit_target_kind pairing CHECK from
-- vocab.FIT_TARGET_RULES; nullable columns carry a `-- why-null:` reason. Booleans are INTEGER 0/1; every
-- *_utc TEXT is ISO-8601 UTC with milliseconds (…Z); every *_json TEXT is json_valid.

-- ==================================================================== tables
-- Applied migrations (`migrations/NNNN_*.sql`), one row each.
CREATE TABLE schema_migration (
  version INTEGER NOT NULL,
  applied_utc TEXT NOT NULL CHECK (applied_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  description TEXT NOT NULL,
  PRIMARY KEY (version)
);

-- A paper iteration (`r2`, `r3`). Changing the round is a new roster version.
CREATE TABLE paper_round (
  round_id TEXT NOT NULL,
  opened_utc TEXT NOT NULL CHECK (opened_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  closed_utc TEXT CHECK (closed_utc IS NULL OR closed_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: the open round has not closed
  description TEXT NOT NULL,
  paper_build_commit TEXT CHECK (paper_build_commit IS NULL OR paper_build_commit GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR paper_build_commit = 'unverified'),  -- why-null: the paper-figures sha roster v1 was transcribed from is pinned after transcription
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (round_id)
);

-- A checkpoint at a pinned revision (base, instruct or chat).
CREATE TABLE model (
  model_id TEXT NOT NULL,
  family TEXT NOT NULL CHECK (family IN ('gemma4', 'qwen35', 'qwen36', 'qwen38', 'nemotron3', 'llama31', 'llama32', 'glm46v')),
  size_label TEXT NOT NULL,
  checkpoint_kind TEXT NOT NULL CHECK (checkpoint_kind IN ('base', 'instruct', 'chat', 'organism')),
  hf_repo TEXT NOT NULL,
  hf_revision TEXT NOT NULL CHECK (hf_revision GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR hf_revision = 'unverified'),
  mirror_of TEXT,  -- why-null: only mirrored repos name their upstream
  chat_template_sha256 TEXT NOT NULL CHECK (chat_template_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR chat_template_sha256 = 'unverified'),
  chat_template_note TEXT,  -- why-null: free-text note, optional
  tokenizer_sha256 TEXT CHECK (tokenizer_sha256 IS NULL OR tokenizer_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR tokenizer_sha256 = 'unverified'),  -- why-null: not recorded for every checkpoint
  generation_config_present INTEGER CHECK (generation_config_present IN (0, 1)),  -- why-null: unverified for a checkpoint never served and never read (reason in field_confidence_json)
  generation_config_json TEXT CHECK (generation_config_json IS NULL OR json_valid(generation_config_json)),  -- why-null: absent when the checkpoint ships no generation_config.json
  generation_config_source_utc TEXT CHECK (generation_config_source_utc IS NULL OR generation_config_source_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: absent when the checkpoint ships no generation_config.json
  thinking_channel TEXT NOT NULL CHECK (thinking_channel IN ('available', 'not_available', 'unverified')),
  thinking_header_moves INTEGER,  -- why-null: only thinking-capable checkpoints record header moves
  architecture_note TEXT,  -- why-null: free text (hybrid Mamba: fused kernels, prefix caching off)
  paper_status TEXT NOT NULL CHECK (paper_status IN ('in_paper', 'descoped', 'reference')),
  paper_status_ruling_id TEXT REFERENCES ruling(ruling_id),  -- why-null: set only when a ruling changed the status
  field_confidence_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_confidence_json)),  -- {column: {confidence, reason}} for every seeded value that is inferred or unverified.
  notes TEXT,  -- why-null: free text
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (model_id)
);

-- Every system instruction or constitution text an object distils or a prompted object declares; the text lives at `source_uri`.
CREATE TABLE si_text (
  si_id TEXT NOT NULL,
  si_text_sha256 TEXT NOT NULL CHECK (si_text_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),
  si_token_count_by_model_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(si_token_count_by_model_json)),
  si_kind TEXT NOT NULL CHECK (si_kind IN ('safety_instruction', 'constitution_short', 'constitution_full', 'irrelevant_control', 'reference_other')),
  source_uri TEXT NOT NULL,
  first_used_utc TEXT CHECK (first_used_utc IS NULL OR first_used_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: unknown for texts recovered from a store
  field_confidence_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_confidence_json)),
  notes TEXT,  -- why-null: free text
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (si_id),
  UNIQUE (si_text_sha256)
);

-- One hyperparameter search.
CREATE TABLE fit_search (
  search_id TEXT NOT NULL,
  campaign TEXT NOT NULL,
  target_object_class_json TEXT NOT NULL CHECK (json_valid(target_object_class_json)),
  method TEXT NOT NULL CHECK (method IN ('sobol', 'grid', 'random', 'bayesian', 'manual', 'reconnaissance')),
  n_trials INTEGER NOT NULL,
  n_trials_completed INTEGER NOT NULL,
  search_space_json TEXT NOT NULL CHECK (json_valid(search_space_json)),
  objective TEXT NOT NULL,
  objective_direction TEXT NOT NULL CHECK (objective_direction IN ('minimize', 'maximize')),
  winner_params_json TEXT CHECK (winner_params_json IS NULL OR json_valid(winner_params_json)),  -- why-null: a search may not have concluded
  winner_trial_id TEXT,  -- why-null: a search may not have concluded
  winner_objective REAL,  -- why-null: a search may not have concluded
  argmin_interior INTEGER CHECK (argmin_interior IN (0, 1)),  -- why-null: only fitted-argmin searches evaluate interiority
  quadratic_fit_positive_definite INTEGER CHECK (quadratic_fit_positive_definite IN (0, 1)),  -- why-null: only quadratic-fit searches
  quadratic_fit_params_json TEXT CHECK (quadratic_fit_params_json IS NULL OR json_valid(quadratic_fit_params_json)),  -- why-null: only quadratic-fit searches
  recentre_rounds INTEGER NOT NULL DEFAULT 0,
  confirmation_trial_id TEXT,  -- why-null: no confirmation trial was run
  confirmation_within_noise INTEGER CHECK (confirmation_within_noise IN (0, 1)),  -- why-null: no confirmation trial was run
  noise_estimate REAL,  -- why-null: no noise estimate was recorded
  grad_norm_reconnaissance_uri TEXT,  -- why-null: no reconnaissance pass
  substrate TEXT NOT NULL CHECK (substrate IN ('cluster_a', 'cluster_b', 'modal', 'grading_host', 'runpod', 'unverified')),  -- `unverified` when no record beside the sweep names the substrate; the missing evidence is named in `field_confidence_json`.
  job_ids_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(job_ids_json)),
  code_sha TEXT NOT NULL CHECK (code_sha GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR code_sha = 'unverified'),
  config_sha256 TEXT CHECK (config_sha256 IS NULL OR config_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR config_sha256 = 'unverified'),  -- why-null: manual searches have no config file
  started_utc TEXT NOT NULL CHECK (started_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  finished_utc TEXT CHECK (finished_utc IS NULL OR finished_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: search in progress
  wandb_sweep_url TEXT,  -- why-null: not every search logged to W&B
  trials_uri TEXT,  -- why-null: the trial log may not be on disk
  producer_session TEXT,  -- why-null: unknown for legacy searches
  field_confidence_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_confidence_json)),
  notes TEXT,  -- why-null: free text
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (search_id)
);

-- One trial of a search.
CREATE TABLE fit_trial (
  search_id TEXT NOT NULL REFERENCES fit_search(search_id),
  trial_id TEXT NOT NULL,
  params_json TEXT NOT NULL CHECK (json_valid(params_json)),
  objective_value REAL,  -- why-null: failed or pruned trials have no objective
  status TEXT NOT NULL CHECK (status IN ('complete', 'failed', 'pruned')),
  clip_fraction REAL,  -- why-null: not every trial log records clipping
  epochs_seen INTEGER,  -- why-null: not every trial log records epochs
  wandb_run_id TEXT,  -- why-null: not every trial logged to W&B
  started_utc TEXT CHECK (started_utc IS NULL OR started_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: trial logs may lack timestamps
  finished_utc TEXT CHECK (finished_utc IS NULL OR finished_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: trial logs may lack timestamps
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (search_id, trial_id)
);

-- The BENCHMARK only, never a variant of it: every GSM8K that ever ran is one `eval_id` with different item sets and instruments.
CREATE TABLE eval (
  eval_id TEXT NOT NULL,
  eval_category TEXT NOT NULL CHECK (eval_category IN ('static_attack', 'multi_turn', 'best_of_n', 'over_refusal', 'capability', 'petri', 'agentic', 'misalignment', 'em_organism', 'omit_params')),
  headline_metric_id TEXT NOT NULL,
  metric_direction TEXT NOT NULL CHECK (metric_direction IN ('higher_is_better', 'lower_is_better')),
  default_item_set_id TEXT,  -- why-null: soft reference (circular with item_set.eval_id); set once item sets exist
  attacker_required INTEGER NOT NULL CHECK (attacker_required IN (0, 1)),
  producer_spellings_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(producer_spellings_json)),
  paper_status TEXT NOT NULL CHECK (paper_status IN ('in_paper', 'appendix', 'dropped')),
  paper_status_ruling_id TEXT REFERENCES ruling(ruling_id),  -- why-null: set only when a ruling changed the status
  field_confidence_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_confidence_json)),
  notes TEXT,  -- why-null: free text
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (eval_id),
  CONSTRAINT eval_headline_metric_id_not_generic CHECK (headline_metric_id NOT IN ('score', 'value', 'metric', 'result', 'accuracy', 'mean', 'count', 'total', 'number', 'frac', 'fraction', 'share', 'pct', 'percent', 'stat', 'statistic', 'measure', 'outcome', 'degenerate', 'degeneration', 'degeneracy', 'degen', 'loop', 'looping', 'loops', 'at_cap', 'capped', 'truncated', 'truncation', 'collapse', 'frac_degenerate', 'degenerate_rate', 'degenerate_frac', 'degenerate_fraction', 'loop_rate', 'frac_loop', 'loop_frac', 'at_cap_rate', 'frac_at_cap', 'at_cap_frac', 'at_cap_fraction', 'classifier', 'frac_classifier', 'classifier_rate', 'classifier_frac', 'classifier_share', 'degen_classifier_share', 'contentless', 'frac_contentless', 'contentless_rate', 'contentless_frac', 'contentless_share', 'degen_contentless_share', 'rep_ratio_loop', 'frac_rep_ratio_loop', 'rep_ratio_loop_rate', 'rep_ratio_loop_frac', 'rep_ratio_loop_share', 'degen_rep_ratio_loop_share', 'zlib_collapse', 'frac_zlib_collapse', 'zlib_collapse_rate', 'zlib_collapse_frac', 'zlib_collapse_share', 'degen_zlib_collapse_share', 'union5', 'frac_union5', 'union5_rate', 'union5_frac', 'union5_share', 'degen_union5_share', 'at_token_cap', 'frac_at_token_cap', 'at_token_cap_rate', 'at_token_cap_frac', 'at_token_cap_share', 'degen_at_token_cap_share', 'at_token_cap_retokenized', 'frac_at_token_cap_retokenized', 'at_token_cap_retokenized_rate', 'at_token_cap_retokenized_frac', 'at_token_cap_retokenized_share', 'degen_at_token_cap_retokenized_share', 'at_token_cap_finish_reason', 'frac_at_token_cap_finish_reason', 'at_token_cap_finish_reason_rate', 'at_token_cap_finish_reason_frac', 'at_token_cap_finish_reason_share', 'degen_at_token_cap_finish_reason_share', 'loop_first512', 'frac_loop_first512', 'loop_first512_rate', 'loop_first512_frac', 'loop_first512_share', 'degen_loop_first512_share', 'defended_degenerate', 'frac_defended_degenerate', 'defended_degenerate_rate', 'defended_degenerate_frac', 'defended_degenerate_share', 'degen_defended_degenerate_share', 'tail_loop', 'frac_tail_loop', 'tail_loop_rate', 'tail_loop_frac', 'tail_loop_share', 'degen_tail_loop_share', 'line_loop', 'frac_line_loop', 'line_loop_rate', 'line_loop_frac', 'line_loop_share', 'degen_line_loop_share', 'truncation_only', 'frac_truncation_only', 'truncation_only_rate', 'truncation_only_frac', 'truncation_only_share', 'degen_truncation_only_share', 'loop_without_cap', 'frac_loop_without_cap', 'loop_without_cap_rate', 'loop_without_cap_frac', 'loop_without_cap_share', 'degen_loop_without_cap_share', 'loop_or_at_cap', 'frac_loop_or_at_cap', 'loop_or_at_cap_rate', 'loop_or_at_cap_frac', 'loop_or_at_cap_share', 'degen_loop_or_at_cap_share', 'at_cap_share', 'loop_share', 'degenerate_share', 'degenerate_share_union5', 'at_cap_share_retokenized', 'at_cap_share_finish_reason', 'frac_degenerate_classifier', 'frac_degenerate_contentless', 'frac_degenerate_rep_ratio_loop', 'frac_degenerate_zlib_collapse', 'frac_degenerate_union5'))
);

-- The exact prompt set: version and subsample.
CREATE TABLE item_set (
  item_set_id TEXT NOT NULL,
  eval_id TEXT REFERENCES eval(eval_id),  -- why-null: a goal pool shared by several evals (the 259-goal jailbreak pool, the EM 8-question set); the per-eval sets reference it through `paired_with:<item_set_id>`
  dataset_version TEXT NOT NULL,
  n_items INTEGER,  -- why-null: unverified when the set's count was never read (reason in field_confidence_json)
  items_sha256 TEXT NOT NULL CHECK (items_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR items_sha256 = 'unverified'),
  source_uri TEXT NOT NULL,
  item_id_scheme TEXT NOT NULL,
  subsample_rule TEXT NOT NULL CHECK (subsample_rule IN ('full', 'fixed_ids_file') OR subsample_rule GLOB 'seeded_sample:*' OR subsample_rule GLOB 'paired_with:*'),
  pairing_note TEXT,  -- why-null: only paired subsamples carry a note
  held_out_of_fit INTEGER CHECK (held_out_of_fit IN (0, 1)),  -- why-null: unknown for external item sets
  field_confidence_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_confidence_json)),
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (item_set_id)
);

-- A judge identity: sha256 over model, rubric sha, protocol sha and threshold rule.
CREATE TABLE judge (
  judge_id TEXT NOT NULL,
  judge_model TEXT NOT NULL,
  judge_role TEXT NOT NULL CHECK (judge_role IN ('judge', 'auditor')),
  rubric_name TEXT NOT NULL,
  rubric_version TEXT NOT NULL,
  rubric_sha256 TEXT NOT NULL CHECK (rubric_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR rubric_sha256 = 'unverified'),
  protocol_sha256 TEXT NOT NULL CHECK (protocol_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR protocol_sha256 = 'unverified'),
  score_scale TEXT NOT NULL,
  threshold_rule TEXT,  -- why-null: label-only judges have no threshold
  label_vocabulary_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(label_vocabulary_json)),
  judge_backend TEXT NOT NULL CHECK (judge_backend IN ('batch', 'live', 'batch_or_live', 'unverified')),
  field_confidence_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_confidence_json)),
  notes TEXT,  -- why-null: free text
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (judge_id)
);

-- The DECLARED measurement setting (harness, n-shot, CoT, thinking, scoring, decode, cap, serving).
CREATE TABLE instrument (
  instrument_id TEXT NOT NULL,
  eval_id TEXT NOT NULL REFERENCES eval(eval_id),
  item_set_id TEXT NOT NULL REFERENCES item_set(item_set_id),
  harness TEXT NOT NULL CHECK (harness IN ('bespoke_sisteer', 'inspect_ai', 'inspect_evals', 'evalplus', 'bfcl_eval', 'pyrit', 'actorattack', 'petri', 'strongreject', 'agentic_misalignment', 'em_organism', 'lm_eval')),
  harness_version TEXT NOT NULL,
  harness_config_hash TEXT NOT NULL,
  n_shot INTEGER,  -- why-null: not a shot task
  prompt_template_sha256 TEXT NOT NULL CHECK (prompt_template_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR prompt_template_sha256 = 'unverified'),
  cot_prompting TEXT CHECK (cot_prompting IN ('none', 'explicit_instruction', 'few_shot_cot')),  -- why-null: not applicable to attack and judge-graded evals
  scoring_rule TEXT NOT NULL CHECK (scoring_rule IN ('exact_match', 'numeric_match', 'sympy_equiv', 'letter_logprob_prefill', 'judge_threshold', 'judge_graded_weights', 'pass_at_1_sandbox', 'ast_match', 'rate_over_scenarios', 'ifeval_checker', 'judge_score_mean')),
  answer_extraction TEXT NOT NULL CHECK (answer_extraction IN ('regex', 'last_number', 'boxed', 'judge', 'none', 'unverified')),
  token_cap_tokens INTEGER,  -- why-null: unverified for a superseded instrument whose cap was never read (reason in field_confidence_json)
  token_cap_ladder_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(token_cap_ladder_json)),
  ladder_promotion_rule TEXT,  -- why-null: a fixed cap has no ladder
  read_at TEXT NOT NULL CHECK (read_at IN ('ladder_final', 'fixed', 'unverified')),
  reply_cap_tokens INTEGER,  -- why-null: only multi-turn instruments cap replies separately
  context_window_tokens INTEGER,  -- why-null: not declared for every instrument
  decode_source TEXT NOT NULL CHECK (decode_source IN ('generation_config', 'vendor_recommendation', 'model_card', 'vllm_default', 'greedy', 'grandfathered_T1', 'runner_forced_T1', 'legacy_contracts_row', 'unverified')),
  decode_temperature REAL,  -- why-null: not sent (engine default) — resolved value in the run's decode_resolved_json
  decode_top_p REAL,  -- why-null: not sent (engine default)
  decode_top_k INTEGER,  -- why-null: not sent (engine default)
  decode_min_p REAL,  -- why-null: not sent (engine default)
  decode_repetition_penalty REAL,  -- why-null: not sent (engine default)
  decode_presence_penalty REAL,  -- why-null: not sent (engine default)
  decode_seed_rule TEXT NOT NULL CHECK (decode_seed_rule IN ('per_item', 'per_draw', 'per_goal_turn', 'per_scenario_turn', 'per_response', 'fixed', 'none', 'unverified')),
  thinking_mode TEXT NOT NULL CHECK (thinking_mode IN ('on', 'off', 'not_available')),
  n_trials INTEGER,  -- why-null: unverified for a superseded instrument whose trial count was never read (reason in field_confidence_json)
  bon_n INTEGER,  -- why-null: only best-of-n instruments
  max_turns INTEGER,  -- why-null: only multi-turn instruments
  serving_path TEXT NOT NULL CHECK (serving_path IN ('lora_native', 'lens', 'passthrough', 'hf', 'unverified')),
  applied_positions_mode TEXT NOT NULL CHECK (applied_positions_mode IN ('all', 'response', 'response_all_turns', 'prompt_last', 'prefill_all', 'prefill_last_broadcast', 'last', 'none', 'unverified')),
  attacker_model_id TEXT REFERENCES model(model_id),  -- why-null: only attacker-driven evals
  attacker_decode_json TEXT CHECK (attacker_decode_json IS NULL OR json_valid(attacker_decode_json)),  -- why-null: only attacker-driven evals
  judge_id TEXT REFERENCES judge(judge_id),  -- why-null: rule-scored evals (exact match, sandbox) have no judge
  prefill_scheme TEXT,  -- why-null: only prefill-scored instruments
  field_confidence_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_confidence_json)),
  notes TEXT,  -- why-null: free text
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (instrument_id)
);

-- THE authority for sampling parameters: one row per model × (eval or eval category) × thinking mode per version.
CREATE TABLE decode_policy (
  policy_id TEXT NOT NULL,
  policy_ref TEXT NOT NULL,  -- Stable name the harness's sampling MODES map to (S8, C34).
  policy_version INTEGER NOT NULL,
  model_id TEXT NOT NULL REFERENCES model(model_id),
  eval_id TEXT REFERENCES eval(eval_id),  -- why-null: a row names an eval OR an eval category (CHECK)
  eval_category TEXT CHECK (eval_category IN ('static_attack', 'multi_turn', 'best_of_n', 'over_refusal', 'capability', 'petri', 'agentic', 'misalignment', 'em_organism', 'omit_params')),  -- why-null: a row names an eval OR an eval category (CHECK)
  thinking_mode TEXT NOT NULL CHECK (thinking_mode IN ('on', 'off', 'not_available')),
  decode_source TEXT NOT NULL CHECK (decode_source IN ('generation_config', 'vendor_recommendation', 'model_card', 'vllm_default', 'greedy', 'grandfathered_T1', 'runner_forced_T1', 'legacy_contracts_row', 'unverified')),
  temperature REAL,  -- why-null: deliberately not sent; what it resolves to is in params_not_sent_json
  top_p REAL,  -- why-null: deliberately not sent; see params_not_sent_json
  top_k INTEGER,  -- why-null: deliberately not sent; see params_not_sent_json
  min_p REAL,  -- why-null: deliberately not sent; see params_not_sent_json
  repetition_penalty REAL,  -- why-null: deliberately not sent; see params_not_sent_json
  presence_penalty REAL,  -- why-null: deliberately not sent; see params_not_sent_json
  max_new_tokens_rule TEXT NOT NULL,
  seed_rule TEXT NOT NULL CHECK (seed_rule IN ('per_item', 'per_draw', 'per_goal_turn', 'per_scenario_turn', 'per_response', 'fixed', 'none', 'unverified')),
  params_not_sent_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(params_not_sent_json)),
  source_citation TEXT NOT NULL,
  ruling_id TEXT REFERENCES ruling(ruling_id),  -- why-null: only grandfathered values cite a ruling
  is_default INTEGER NOT NULL DEFAULT 1 CHECK (is_default IN (0, 1)),  -- The default policy for its (model, eval-or-category, thinking) key (C34).
  effective_from_utc TEXT NOT NULL CHECK (effective_from_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z' OR effective_from_utc = 'unverified'),  -- Ruling date at midnight UTC (date-only rulings; `extra_json.effective_from_confidence`), or `unverified` with a reason.
  superseded_by_policy_id TEXT REFERENCES decode_policy(policy_id),  -- why-null: current policies are not superseded
  field_confidence_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_confidence_json)),
  notes TEXT,  -- why-null: free text
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (policy_id),
  UNIQUE (policy_ref, policy_version),
  CONSTRAINT decode_policy_eval_xor_category CHECK ((eval_id IS NULL) <> (eval_category IS NULL))
);

-- Harness sampling MODE → decode_policy row (`contracts.sampling_for(model_key, mode)`; S8, C34).
CREATE TABLE sampling_mode_policy (
  model_id TEXT NOT NULL REFERENCES model(model_id),
  sampling_mode TEXT NOT NULL CHECK (sampling_mode IN ('card', 'thinking_card', 'general', 'battery', 'greedy', 'vendor_preset')),
  policy_id TEXT NOT NULL REFERENCES decode_policy(policy_id),
  notes TEXT,  -- why-null: free text
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (model_id, sampling_mode)
);

-- A statistic's algorithm, version and seed provenance (F9); joins the run_metric / run_contrast keys.
CREATE TABLE computation (
  computation_id TEXT NOT NULL,
  algorithm TEXT NOT NULL,
  version TEXT NOT NULL,
  seed_provenance TEXT NOT NULL,
  code_sha TEXT NOT NULL CHECK (code_sha GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR code_sha = 'unverified'),
  notes TEXT,  -- why-null: free text
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (computation_id)
);

-- A user ruling (include / exclude / supersede / coexist / operating_point / descope / drop_eval / reference); self-retiring when `expires_when_json` is set.
CREATE TABLE ruling (
  ruling_id TEXT NOT NULL,
  round_id TEXT NOT NULL REFERENCES paper_round(round_id),
  action TEXT NOT NULL CHECK (action IN ('include', 'exclude', 'supersede', 'coexist', 'operating_point', 'descope', 'drop_eval', 'reference', 'hold_out')),
  scope_kind TEXT NOT NULL CHECK (scope_kind IN ('run', 'object', 'model', 'eval', 'key', 'comparison')),
  scope_json TEXT NOT NULL CHECK (json_valid(scope_json)),
  target_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(target_json)),
  expires_when_json TEXT CHECK (expires_when_json IS NULL OR json_valid(expires_when_json)),  -- why-null: not every ruling is self-retiring
  expired_utc TEXT CHECK (expired_utc IS NULL OR expired_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: stamped once, when found-and-resolving evidence first said the condition held; never deleted
  evidence_state TEXT NOT NULL DEFAULT 'not_evaluated' CHECK (evidence_state IN ('ok', 'missing', 'path_absent', 'incoherent', 'stale', 'not_evaluated')),
  evidence_evaluated_utc TEXT CHECK (evidence_evaluated_utc IS NULL OR evidence_evaluated_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: no evaluation has run yet
  reason TEXT NOT NULL,
  ruled_utc TEXT NOT NULL CHECK (ruled_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  ruled_utc_precision TEXT NOT NULL DEFAULT 'datetime' CHECK (ruled_utc_precision IN ('datetime', 'date')),  -- Many recorded rulings are date-only; `date` means ruled_utc carries midnight UTC of that day.
  ruled_by TEXT NOT NULL,
  source_ref TEXT NOT NULL,
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (ruling_id)
);

-- One expiry / evidence evaluation of a ruling (a harvester record); `ruling.evidence_state` / `expired_utc` are recomputed from these rows.
CREATE TABLE ruling_state (
  ruling_id TEXT NOT NULL REFERENCES ruling(ruling_id),
  evaluated_utc TEXT NOT NULL CHECK (evaluated_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  evidence_state TEXT NOT NULL CHECK (evidence_state IN ('ok', 'missing', 'path_absent', 'incoherent', 'stale', 'not_evaluated')),
  expired INTEGER NOT NULL CHECK (expired IN (0, 1)),
  evidence_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(evidence_json)),
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (ruling_id, evaluated_utc)
);

-- The fitted or declared intervention, with its complete fit record.
CREATE TABLE object (
  object_id TEXT NOT NULL,
  object_kind TEXT NOT NULL CHECK (object_kind IN ('none', 'system_instruction', 'lora', 'lora_subtraction', 'relu_steer', 'relu_steer_distilled_difference', 'vector', 'vector_all', 'diffmean', 'static_r_arditi', 'caa_static_r', 'alphasteer', 'antidote', 'composed', 'stacked')),
  paper_label TEXT NOT NULL CHECK (paper_label IN ('none', 'safety_si', 'constitution_si', 'constitution_si_full', 'control_lora', 'constitution_lora', 'difference_lora', 'control_relu', 'constitution_relu', 'difference_relu', 'difference_relu_distilled', 'arditi', 'arditi_allpos', 'alphasteer_rebake', 'alphasteer_as_fit', 'alphasteer_refit_reference', 'safety_lora', 'safety_relu', 'other')),
  campaign TEXT NOT NULL,
  campaign_cell_id_legacy TEXT,  -- why-null: natively emitted objects carry no legacy id
  object_role TEXT NOT NULL CHECK (object_role IN ('constitution', 'control', 'difference', 'safety', 'irrelevant', 'baseline_none', 'baseline_published', 'prompt')),
  fit_target_kind TEXT NOT NULL CHECK (fit_target_kind IN ('system_instruction_distillation', 'corpus_document_fit', 'contrastive_direction', 'derived', 'declared_prompt', 'none')),
  fit_teacher_si_id TEXT REFERENCES si_text(si_id),  -- why-null: only system_instruction_distillation (paired-nullness CHECK)
  fit_teacher_si_text_sha256 TEXT CHECK (fit_teacher_si_text_sha256 IS NULL OR fit_teacher_si_text_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]') REFERENCES si_text(si_text_sha256),  -- why-null: only system_instruction_distillation (paired-nullness CHECK)
  fit_prompt_pool_id TEXT,  -- why-null: only system_instruction_distillation (paired-nullness CHECK)
  fit_prompt_pool_sha256 TEXT CHECK (fit_prompt_pool_sha256 IS NULL OR fit_prompt_pool_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR fit_prompt_pool_sha256 = 'unverified'),  -- why-null: only system_instruction_distillation (paired-nullness CHECK)
  fit_corpus_id TEXT,  -- why-null: only corpus_document_fit (paired-nullness CHECK)
  fit_corpus_description TEXT,  -- why-null: only corpus_document_fit; optional description
  fit_corpus_sha256 TEXT CHECK (fit_corpus_sha256 IS NULL OR fit_corpus_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR fit_corpus_sha256 = 'unverified'),  -- why-null: only corpus_document_fit (paired-nullness CHECK)
  fit_corpus_n_documents INTEGER,  -- why-null: only corpus_document_fit; not every sidecar records it
  fit_corpus_n_tokens INTEGER,  -- why-null: only corpus_document_fit; not every sidecar records it
  fit_contrast_sets_json TEXT CHECK (fit_contrast_sets_json IS NULL OR json_valid(fit_contrast_sets_json)),  -- why-null: only contrastive_direction (paired-nullness CHECK)
  fit_model_id TEXT REFERENCES model(model_id),  -- why-null: `none` and declared-prompt objects were not fit
  fit_chat_template_sha256 TEXT CHECK (fit_chat_template_sha256 IS NULL OR fit_chat_template_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR fit_chat_template_sha256 = 'unverified'),  -- why-null: `none` and declared-prompt objects were not fit
  fit_thinking_render TEXT NOT NULL CHECK (fit_thinking_render IN ('on', 'off', 'not_applicable', 'unverified')),
  fit_objective TEXT NOT NULL CHECK (fit_objective IN ('ce', 'kl', 'diffmean', 'arditi_search', 'alphasteer', 'antidote', 'not_applicable')),
  fit_positions TEXT NOT NULL CHECK (fit_positions IN ('all', 'response_incl_assistant_header', 'last_token_of_appended_assistant_header', 'searched_post_instruction_span', 'completion_mean', 'inherited_from_parents', 'not_applicable', 'unverified')),
  fit_response_header_len INTEGER,  -- why-null: only response_incl_assistant_header positions
  fit_capture_site TEXT CHECK (fit_capture_site IN ('resid_pre', 'resid_post')),  -- why-null: only captured directions name a site
  fit_selected_position_offset INTEGER,  -- why-null: only searched positions (Arditi)
  fit_selected_token_text TEXT,  -- why-null: only searched positions (Arditi)
  fit_layers_json TEXT CHECK (fit_layers_json IS NULL OR json_valid(fit_layers_json)),  -- why-null: `none` and declared-prompt objects have no layers
  fit_layer_index_convention TEXT CHECK (fit_layer_index_convention IN ('zero_based_decoder_block', 'one_based', 'hf_module_path')),  -- why-null: `none` and declared-prompt objects have no layers
  fit_layer_count INTEGER,  -- why-null: `none` and declared-prompt objects have no layers
  fit_layer_selection_rule TEXT CHECK (fit_layer_selection_rule IN ('all', 'listed_in_config', 'separability_search', 'published_set', 'inherited')),  -- why-null: `none` and declared-prompt objects have no layers
  served_layer_shift INTEGER,  -- why-null: only objects served at a shifted layer
  fit_rank INTEGER,  -- why-null: LoRA objects only
  fit_alpha REAL,  -- why-null: LoRA objects only
  fit_target_modules_json TEXT CHECK (fit_target_modules_json IS NULL OR json_valid(fit_target_modules_json)),  -- why-null: LoRA objects only
  fit_pool_sha256 TEXT CHECK (fit_pool_sha256 IS NULL OR fit_pool_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR fit_pool_sha256 = 'unverified'),  -- why-null: not every fit names a pool
  fit_sample_manifest_sha256 TEXT CHECK (fit_sample_manifest_sha256 IS NULL OR fit_sample_manifest_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR fit_sample_manifest_sha256 = 'unverified'),  -- why-null: not every fit writes a sample manifest
  fit_completion_tokens INTEGER,  -- why-null: not every sidecar records it
  fit_heldout_fraction REAL,  -- why-null: not every fit holds out
  fit_split_seed INTEGER,  -- why-null: not every fit records a split seed
  fit_probe_sources_pinned_out INTEGER CHECK (fit_probe_sources_pinned_out IN (0, 1)),  -- why-null: not every fit records it
  fit_hyperparameters_json TEXT CHECK (fit_hyperparameters_json IS NULL OR json_valid(fit_hyperparameters_json)),  -- why-null: `none` and declared-prompt objects were not fit
  fit_lr REAL,  -- why-null: not applicable to unfitted objects
  fit_lr_schedule TEXT,  -- why-null: not applicable to unfitted objects
  fit_effective_batch INTEGER,  -- why-null: not applicable to unfitted objects
  fit_realized_batch_json TEXT CHECK (fit_realized_batch_json IS NULL OR json_valid(fit_realized_batch_json)),  -- why-null: not applicable to unfitted objects
  fit_epochs_cap INTEGER,  -- why-null: not applicable to unfitted objects
  fit_epochs_seen INTEGER,  -- why-null: not applicable to unfitted objects
  fit_best_epoch INTEGER,  -- why-null: not applicable to unfitted objects
  fit_patience INTEGER,  -- why-null: not applicable to unfitted objects
  fit_early_stopped INTEGER CHECK (fit_early_stopped IN (0, 1)),  -- why-null: not applicable to unfitted objects
  fit_stopped_on TEXT CHECK (fit_stopped_on IN ('patience', 'epoch_cap', 'unverified')),  -- why-null: not applicable to unfitted objects
  fit_steps INTEGER,  -- why-null: not applicable to unfitted objects
  fit_clip_fraction REAL,  -- why-null: not applicable to unfitted objects
  fit_final_train_loss REAL,  -- why-null: not applicable to unfitted objects
  fit_final_heldout_loss REAL,  -- why-null: not applicable to unfitted objects
  fit_best_heldout_loss REAL,  -- why-null: not applicable to unfitted objects
  fit_heldout_curve_uri TEXT,  -- why-null: not applicable to unfitted objects
  fit_seed INTEGER,  -- why-null: unknown seeds are `fit_seed_confidence = unverified`, never a guessed number
  fit_seed_confidence TEXT NOT NULL CHECK (fit_seed_confidence IN ('recorded', 'assumed_default_0', 'not_applicable', 'unverified')),
  fit_replicate_label TEXT,  -- why-null: only replicate fits carry a label
  fit_search_id TEXT REFERENCES fit_search(search_id),  -- why-null: only searched hyperparameters link a search
  fit_lr_selected_by TEXT CHECK (fit_lr_selected_by IS NULL OR fit_lr_selected_by IN ('search', 'default', 'manual', 'unverified') OR fit_lr_selected_by GLOB 'inherited_from:*'),  -- why-null: not applicable to unfitted objects
  fit_argmin_interior INTEGER CHECK (fit_argmin_interior IN (0, 1)),  -- why-null: only searched learning rates
  fit_code_sha TEXT CHECK (fit_code_sha IS NULL OR fit_code_sha GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR fit_code_sha = 'unverified'),  -- why-null: not applicable to unfitted objects
  fit_config_path TEXT,  -- why-null: not applicable to unfitted objects
  fit_config_sha256 TEXT CHECK (fit_config_sha256 IS NULL OR fit_config_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR fit_config_sha256 = 'unverified'),  -- why-null: not applicable to unfitted objects
  fit_writer TEXT,  -- why-null: not applicable to unfitted objects
  fit_started_utc TEXT CHECK (fit_started_utc IS NULL OR fit_started_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: not applicable to unfitted objects
  fit_finished_utc TEXT CHECK (fit_finished_utc IS NULL OR fit_finished_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: not applicable to unfitted objects
  fit_walltime_s REAL,  -- why-null: walltime is recorded where known, never estimated
  fit_substrate TEXT CHECK (fit_substrate IN ('cluster_a', 'cluster_b', 'modal', 'grading_host', 'runpod')),  -- why-null: not applicable to unfitted objects
  fit_job_id TEXT,  -- why-null: not applicable to unfitted objects
  fit_node_hostname TEXT,  -- why-null: not applicable to unfitted objects
  fit_gpu_type TEXT,  -- why-null: not applicable to unfitted objects
  fit_gpu_count INTEGER,  -- why-null: not applicable to unfitted objects
  fit_wandb_run_id TEXT,  -- why-null: not every fit logged to W&B
  fit_wandb_url TEXT,  -- why-null: not every fit logged to W&B
  fit_producer_session TEXT,  -- why-null: unknown for legacy fits
  derivation TEXT NOT NULL CHECK (derivation IN ('none', 'lora_subtraction', 'residual_distillation', 'dose_scale', 'composition', 'stack')),
  parent_object_ids_json TEXT CHECK (parent_object_ids_json IS NULL OR json_valid(parent_object_ids_json)),  -- why-null: only derived objects (paired-nullness CHECK)
  derivation_params_json TEXT CHECK (derivation_params_json IS NULL OR json_valid(derivation_params_json)),  -- why-null: only derived objects (paired-nullness CHECK)
  base_scale REAL,  -- why-null: only scaled objects
  si_text_sha256 TEXT CHECK (si_text_sha256 IS NULL OR si_text_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]') REFERENCES si_text(si_text_sha256),  -- why-null: only declared prompts (paired-nullness CHECK)
  si_token_count INTEGER,  -- why-null: only declared prompts (paired-nullness CHECK)
  artifact_sha256 TEXT NOT NULL,  -- The object's bytes (sha256); `none` for the unsteered object; the text sha for a declared prompt.
  artifact_bytes INTEGER,  -- why-null: `none` and declared-prompt objects have no artifact file
  artifact_locations_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(artifact_locations_json)),
  object_sidecars_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(object_sidecars_json)),
  status TEXT NOT NULL CHECK (status IN ('approved', 'reference', 'superseded', 'withdrawn', 'pending_fit')),
  superseded_by_object_id TEXT REFERENCES object(object_id),  -- why-null: only superseded objects
  status_ruling_id TEXT REFERENCES ruling(ruling_id),  -- why-null: set only when a ruling set the status
  field_confidence_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_confidence_json)),
  notes TEXT,  -- why-null: free text
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (object_id),
  CONSTRAINT object_fit_target_kind_pairing CHECK (
     (fit_target_kind = 'system_instruction_distillation'
         AND fit_objective IN ('kl', 'ce')
         AND derivation IN ('none')
         AND fit_teacher_si_id IS NOT NULL
         AND fit_teacher_si_text_sha256 IS NOT NULL
         AND fit_prompt_pool_id IS NOT NULL
         AND fit_prompt_pool_sha256 IS NOT NULL
         AND fit_model_id IS NOT NULL
         AND fit_layers_json IS NOT NULL
         AND fit_corpus_id IS NULL
         AND fit_corpus_sha256 IS NULL
         AND fit_corpus_n_documents IS NULL
         AND fit_corpus_n_tokens IS NULL
         AND fit_corpus_description IS NULL
         AND fit_contrast_sets_json IS NULL
         AND parent_object_ids_json IS NULL
         AND derivation_params_json IS NULL
         AND si_text_sha256 IS NULL
         AND si_token_count IS NULL)
  OR (fit_target_kind = 'corpus_document_fit'
         AND fit_objective IN ('ce')
         AND derivation IN ('none')
         AND fit_corpus_id IS NOT NULL
         AND fit_corpus_sha256 IS NOT NULL
         AND fit_model_id IS NOT NULL
         AND fit_layers_json IS NOT NULL
         AND fit_teacher_si_id IS NULL
         AND fit_teacher_si_text_sha256 IS NULL
         AND fit_prompt_pool_id IS NULL
         AND fit_prompt_pool_sha256 IS NULL
         AND fit_contrast_sets_json IS NULL
         AND parent_object_ids_json IS NULL
         AND derivation_params_json IS NULL
         AND si_text_sha256 IS NULL
         AND si_token_count IS NULL)
  OR (fit_target_kind = 'contrastive_direction'
         AND fit_objective IN ('diffmean', 'arditi_search', 'alphasteer', 'antidote')
         AND derivation IN ('none')
         AND fit_contrast_sets_json IS NOT NULL
         AND fit_model_id IS NOT NULL
         AND fit_layers_json IS NOT NULL
         AND fit_teacher_si_id IS NULL
         AND fit_teacher_si_text_sha256 IS NULL
         AND fit_prompt_pool_id IS NULL
         AND fit_prompt_pool_sha256 IS NULL
         AND fit_corpus_id IS NULL
         AND fit_corpus_sha256 IS NULL
         AND fit_corpus_n_documents IS NULL
         AND fit_corpus_n_tokens IS NULL
         AND fit_corpus_description IS NULL
         AND parent_object_ids_json IS NULL
         AND derivation_params_json IS NULL
         AND si_text_sha256 IS NULL
         AND si_token_count IS NULL)
  OR (fit_target_kind = 'derived'
         AND fit_objective IN ('not_applicable')
         AND derivation IN ('lora_subtraction', 'residual_distillation', 'dose_scale', 'composition', 'stack')
         AND parent_object_ids_json IS NOT NULL
         AND fit_teacher_si_id IS NULL
         AND fit_teacher_si_text_sha256 IS NULL
         AND fit_prompt_pool_id IS NULL
         AND fit_prompt_pool_sha256 IS NULL
         AND fit_corpus_id IS NULL
         AND fit_corpus_sha256 IS NULL
         AND fit_corpus_n_documents IS NULL
         AND fit_corpus_n_tokens IS NULL
         AND fit_corpus_description IS NULL
         AND fit_contrast_sets_json IS NULL
         AND si_text_sha256 IS NULL
         AND si_token_count IS NULL)
  OR (fit_target_kind = 'declared_prompt'
         AND fit_objective IN ('not_applicable')
         AND derivation IN ('none')
         AND object_kind = 'system_instruction'
         AND si_text_sha256 IS NOT NULL
         AND fit_teacher_si_id IS NULL
         AND fit_teacher_si_text_sha256 IS NULL
         AND fit_prompt_pool_id IS NULL
         AND fit_prompt_pool_sha256 IS NULL
         AND fit_corpus_id IS NULL
         AND fit_corpus_sha256 IS NULL
         AND fit_corpus_n_documents IS NULL
         AND fit_corpus_n_tokens IS NULL
         AND fit_corpus_description IS NULL
         AND fit_contrast_sets_json IS NULL
         AND parent_object_ids_json IS NULL
         AND derivation_params_json IS NULL)
  OR (fit_target_kind = 'none'
         AND fit_objective IN ('not_applicable')
         AND derivation IN ('none')
         AND object_kind = 'none'
         AND fit_teacher_si_id IS NULL
         AND fit_teacher_si_text_sha256 IS NULL
         AND fit_prompt_pool_id IS NULL
         AND fit_prompt_pool_sha256 IS NULL
         AND fit_corpus_id IS NULL
         AND fit_corpus_sha256 IS NULL
         AND fit_corpus_n_documents IS NULL
         AND fit_corpus_n_tokens IS NULL
         AND fit_corpus_description IS NULL
         AND fit_contrast_sets_json IS NULL
         AND parent_object_ids_json IS NULL
         AND derivation_params_json IS NULL
         AND si_text_sha256 IS NULL
         AND si_token_count IS NULL)
  )
);
CREATE INDEX idx_object_artifact_sha ON object (artifact_sha256) WHERE artifact_sha256 <> 'none' AND artifact_sha256 NOT LIKE 'si:%';

-- One execution that produced rows, at the registry grain (producer key × producer object key × eval × instrument).
CREATE TABLE run (
  run_id TEXT NOT NULL,  -- `identity.run_id(campaign, producer_key, producer_object_key, eval_id, instrument_id)`.
  campaign TEXT NOT NULL,
  producer_run_key_legacy TEXT NOT NULL,  -- The producer's own EXECUTION key verbatim (F1).
  producer_object_key_legacy TEXT NOT NULL,  -- The producer's OBJECT discriminator within that key (S1); `none` for an unsteered execution.
  lifecycle_state TEXT NOT NULL CHECK (lifecycle_state IN ('queued', 'running', 'generated', 'judging', 'judged', 'ingested', 'failed', 'cancelled', 'superseded', 'withdrawn')),
  queued_utc TEXT CHECK (queued_utc IS NULL OR queued_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: set when the state is reached (trigger trg_run_state_utc requires it from `queued` on)
  started_utc TEXT CHECK (started_utc IS NULL OR started_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: set when the state is reached (trigger trg_run_state_utc requires it from `running` on)
  generated_utc TEXT CHECK (generated_utc IS NULL OR generated_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: set when the state is reached (trigger trg_run_state_utc requires it from `generated` on)
  judged_utc TEXT CHECK (judged_utc IS NULL OR judged_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: set when the state is reached (trigger trg_run_state_utc requires it from `judged` on)
  ingested_utc TEXT CHECK (ingested_utc IS NULL OR ingested_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: set by the harvester's run_ingest record (trigger requires it at `ingested`)
  finished_utc TEXT CHECK (finished_utc IS NULL OR finished_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: terminal time of failed / cancelled runs (trigger requires it for those states)
  walltime_s REAL,  -- why-null: recorded where sacct / Modal / the store span allow, never estimated
  walltime_source TEXT CHECK (walltime_source IN ('sacct', 'modal_call', 'store_span')),  -- why-null: null when walltime_s is null
  model_id TEXT NOT NULL REFERENCES model(model_id),
  model_revision TEXT CHECK (model_revision IS NULL OR model_revision GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR model_revision = 'unverified'),  -- why-null: observed at serving (RUN_VERIFIED_FIELDS); legacy rows may lack it
  object_id TEXT NOT NULL REFERENCES object(object_id),
  transfer_kind TEXT NOT NULL CHECK (transfer_kind IN ('base_to_instruct', 'instruct_direct', 'chat_checkpoint', 'prompted_only', 'none', 'not_applicable')),
  strength_coefficient REAL,  -- why-null: `none` and prompted objects have no coefficient
  strength_nominal REAL,  -- why-null: `none` and prompted objects have no nominal dose
  strength_nominal_source TEXT CHECK (strength_nominal_source IN ('filed', 'derived')),  -- why-null: null when strength_nominal is null
  strength_unit TEXT NOT NULL DEFAULT 'unverified' CHECK (strength_unit IN ('lora_write_basis_multiplier', 'psr_direction_norm_multiplier', 'alpha', 'lambda', 'raw_coefficient', 'nominal_only', 'unverified')),  -- the unit of strength_nominal: two dose ladders scaling different quantities never join into one curve
  is_operating_point INTEGER CHECK (is_operating_point IN (0, 1)),  -- why-null: unknown without an operating_point ruling
  operating_point_id_legacy TEXT,  -- why-null: only producers that filed an operating-point id
  eval_id TEXT NOT NULL REFERENCES eval(eval_id),
  item_set_id TEXT NOT NULL REFERENCES item_set(item_set_id),
  instrument_id TEXT NOT NULL REFERENCES instrument(instrument_id),
  instrument_match TEXT NOT NULL CHECK (instrument_match IN ('match', 'mismatch', 'unverified')),
  harness TEXT NOT NULL CHECK (harness IN ('bespoke_sisteer', 'inspect_ai', 'inspect_evals', 'evalplus', 'bfcl_eval', 'pyrit', 'actorattack', 'petri', 'strongreject', 'agentic_misalignment', 'em_organism', 'lm_eval')),
  harness_version TEXT NOT NULL,
  n_shot INTEGER,  -- why-null: not a shot task
  cot_prompting TEXT CHECK (cot_prompting IN ('none', 'explicit_instruction', 'few_shot_cot')),  -- why-null: not applicable to attack and judge-graded evals
  scoring_rule TEXT NOT NULL CHECK (scoring_rule IN ('exact_match', 'numeric_match', 'sympy_equiv', 'letter_logprob_prefill', 'judge_threshold', 'judge_graded_weights', 'pass_at_1_sandbox', 'ast_match', 'rate_over_scenarios', 'ifeval_checker', 'judge_score_mean')),
  prompt_template_sha256 TEXT NOT NULL CHECK (prompt_template_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR prompt_template_sha256 = 'unverified'),
  judge_id TEXT REFERENCES judge(judge_id),  -- why-null: primary judge; null before any judgment and for rule-scored evals
  pass_label TEXT,  -- why-null: only coexisting re-measurements carry a pass label
  trial_index INTEGER NOT NULL DEFAULT 0,
  n_items_planned INTEGER,  -- why-null: unknown for legacy stores
  n_items_generated INTEGER,  -- why-null: not yet generated
  n_items_judged INTEGER,  -- why-null: not yet judged
  seed_base INTEGER,  -- why-null: only seeded decodes
  decode_seed_rule TEXT NOT NULL CHECK (decode_seed_rule IN ('per_item', 'per_draw', 'per_goal_turn', 'per_scenario_turn', 'per_response', 'fixed', 'none', 'unverified')),
  decode_policy_id TEXT REFERENCES decode_policy(policy_id),  -- why-null: derived (decode_match.stamp_run_rows from v_run_decode_policy_match): set only when decode_policy_match = exact
  decode_policy_match TEXT NOT NULL DEFAULT 'no_policy' CHECK (decode_policy_match IN ('exact', 'ambiguous', 'no_match', 'unrecorded', 'no_policy')),  -- Derived per run from v_run_decode_policy_match (exact / ambiguous / no_match / unrecorded); `no_policy` = the producer's placeholder before derivation.
  decode_sent_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(decode_sent_json)),
  decode_resolved_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(decode_resolved_json)),
  decode_temperature_sent REAL,  -- why-null: not sent (resolved value in decode_resolved_json)
  decode_top_p_sent REAL,  -- why-null: not sent (resolved value in decode_resolved_json)
  decode_top_k_sent INTEGER,  -- why-null: not sent (resolved value in decode_resolved_json)
  decode_source TEXT NOT NULL CHECK (decode_source IN ('generation_config', 'vendor_recommendation', 'model_card', 'vllm_default', 'greedy', 'grandfathered_T1', 'runner_forced_T1', 'legacy_contracts_row', 'unverified')),
  token_cap_tokens INTEGER NOT NULL,
  token_cap_rung_index INTEGER,  -- why-null: a fixed cap has no ladder
  token_cap_ladder_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(token_cap_ladder_json)),
  reply_cap_tokens INTEGER,  -- why-null: only multi-turn runs cap replies separately
  context_window_tokens INTEGER,  -- why-null: observed at serving; legacy rows may lack it
  served_max_num_seqs INTEGER,  -- why-null: observed at serving; legacy rows may lack it
  served_max_num_seqs_source TEXT CHECK (served_max_num_seqs_source IN ('attested', 'runner_concurrency')),  -- why-null: null when served_max_num_seqs is null
  thinking_mode TEXT NOT NULL CHECK (thinking_mode IN ('on', 'off', 'not_available')),
  serving_path TEXT NOT NULL CHECK (serving_path IN ('lora_native', 'lens', 'passthrough', 'hf', 'unverified')),
  serving_engine_version TEXT,  -- why-null: observed at serving; legacy rows may lack it
  serving_identity TEXT,  -- why-null: observed at serving; legacy rows may lack it
  serving_config_sha256 TEXT CHECK (serving_config_sha256 IS NULL OR serving_config_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR serving_config_sha256 = 'unverified'),  -- why-null: observed at serving; legacy rows may lack it
  adapter_fingerprint TEXT,  -- why-null: only natively served adapters
  applied_positions_mode TEXT NOT NULL CHECK (applied_positions_mode IN ('all', 'response', 'response_all_turns', 'prompt_last', 'prefill_all', 'prefill_last_broadcast', 'last', 'none', 'unverified')),
  applied_layers_json TEXT CHECK (applied_layers_json IS NULL OR json_valid(applied_layers_json)),  -- why-null: `none` objects have no layers
  multi_turn_steering_scope TEXT NOT NULL CHECK (multi_turn_steering_scope IN ('every_turn_prefill_and_decode', 'final_header_and_current_decode_only', 'every_assistant_span', 'prefill_only_each_turn', 'single_turn', 'not_applicable', 'unverified')),
  history_resent_each_turn INTEGER CHECK (history_resent_each_turn IN (0, 1)),  -- why-null: single-turn runs
  prefix_cache_policy TEXT CHECK (prefix_cache_policy IN ('on', 'off', 'skip_reading')),  -- why-null: not recorded for every serving path
  intervention_hash TEXT,  -- why-null: `none` objects and legacy rows
  harness_config_hash TEXT,  -- why-null: legacy rows may lack it
  env_digest TEXT,  -- why-null: legacy rows may lack it
  code_sha TEXT NOT NULL CHECK (code_sha GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR code_sha = 'unverified'),
  code_branch TEXT NOT NULL DEFAULT 'unknown',  -- `unknown` when code_sha is not an ancestor of origin/main or a known branch (Fixed decision 23).
  config_path TEXT,  -- why-null: not every run launched from a config file
  config_sha256 TEXT CHECK (config_sha256 IS NULL OR config_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR config_sha256 = 'unverified'),  -- why-null: not every run launched from a config file
  submit_sha_pin TEXT CHECK (submit_sha_pin IS NULL OR submit_sha_pin GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR submit_sha_pin = 'unverified'),  -- why-null: only registered submissions carry a pin
  substrate TEXT NOT NULL CHECK (substrate IN ('cluster_a', 'cluster_b', 'modal', 'grading_host', 'runpod')),
  substrate_source TEXT NOT NULL CHECK (substrate_source IN ('recorded', 'derived', 'assumed_default', 'inferred', 'unverified')),
  cluster_job_id TEXT,  -- why-null: only cluster runs
  job_name TEXT,  -- why-null: only cluster runs
  node_hostname TEXT,  -- why-null: set at job start
  gpu_type TEXT,  -- why-null: derived from inventory or nvidia-smi where available
  gpu_count INTEGER,  -- why-null: set at job start
  modal_app_id TEXT,  -- why-null: only Modal runs
  modal_call_id TEXT,  -- why-null: only Modal runs launched after native emission
  wandb_run_id TEXT,  -- why-null: only runs that logged to W&B
  attacker_model_id TEXT REFERENCES model(model_id),  -- why-null: only attacker-driven evals
  attacker_identity_attested INTEGER CHECK (attacker_identity_attested IN (0, 1)),  -- why-null: only attacker-driven evals
  store_uri TEXT,  -- why-null: a queued run has no store yet
  store_completion_artifact_uri TEXT,  -- why-null: set at generation
  store_completion_sha256 TEXT CHECK (store_completion_sha256 IS NULL OR store_completion_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR store_completion_sha256 = 'unverified'),  -- why-null: set at generation
  view_legacy TEXT,  -- why-null: only backfilled rows carry the producer's legacy transfer-setting string
  lane_source_legacy TEXT,  -- why-null: only backfilled rows carry the paper's source string
  campaign_cell_id_legacy TEXT,  -- why-null: only backfilled rows carry the producer's legacy id
  producer_session TEXT,  -- why-null: unknown for legacy rows
  status_ruling_id TEXT REFERENCES ruling(ruling_id),  -- why-null: set only when a ruling changed the status
  superseded_by_run_id TEXT REFERENCES run(run_id),  -- why-null: only superseded runs
  field_confidence_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_confidence_json)),
  notes TEXT,  -- why-null: free text
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (run_id),
  UNIQUE (producer_run_key_legacy, producer_object_key_legacy, eval_id, instrument_id)
);
CREATE INDEX idx_run_key ON run (model_id, object_id, eval_id, instrument_id);
CREATE INDEX idx_run_lifecycle ON run (lifecycle_state);
CREATE INDEX idx_run_campaign ON run (campaign);
CREATE INDEX idx_run_cluster_job ON run (cluster_job_id);

-- Every lifecycle transition with its evidence; the scheduler's state is stored beside it, never as the truth.
CREATE TABLE run_state_event (
  run_id TEXT NOT NULL REFERENCES run(run_id),
  state TEXT NOT NULL CHECK (state IN ('queued', 'running', 'generated', 'judging', 'judged', 'ingested', 'failed', 'cancelled', 'superseded', 'withdrawn')),
  event_utc TEXT NOT NULL CHECK (event_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  evidence_kind TEXT NOT NULL CHECK (evidence_kind IN ('submit_wrapper', 'job_log', 'completion_artifact', 'scheduler_state', 'ruling', 'harvester')),
  evidence_uri TEXT NOT NULL DEFAULT '',  -- '' when the evidence is not a file.
  scheduler_state TEXT,  -- why-null: only cluster / Modal evidence carries a scheduler state
  note TEXT,  -- why-null: free text
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (run_id, state, event_utc, evidence_uri)
);

-- A judging of a run by one judge; two judges of one run are two rows.
CREATE TABLE judgment (
  judgment_id TEXT NOT NULL,
  run_id TEXT NOT NULL REFERENCES run(run_id),
  judge_id TEXT NOT NULL REFERENCES judge(judge_id),
  started_utc TEXT CHECK (started_utc IS NULL OR started_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: a claim carries claimed_utc only
  finished_utc TEXT CHECK (finished_utc IS NULL OR finished_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: in progress
  n_items_judged INTEGER,  -- why-null: in progress
  n_judge_refusals INTEGER,  -- why-null: in progress or not counted
  n_errors INTEGER,  -- why-null: in progress or not counted
  judge_cache_kind TEXT,  -- why-null: not every driver names a cache
  api_pool TEXT CHECK (api_pool IN ('lowprio', 'highprio', 'batch')),  -- why-null: unknown for legacy judgments
  batch_ids_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(batch_ids_json)),
  grading_code_sha TEXT CHECK (grading_code_sha IS NULL OR grading_code_sha GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR grading_code_sha = 'unverified'),  -- why-null: unknown for legacy judgments
  grading_config_sha256 TEXT CHECK (grading_config_sha256 IS NULL OR grading_config_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR grading_config_sha256 = 'unverified'),  -- why-null: not every driver has a config
  rubric_sha256 TEXT CHECK (rubric_sha256 IS NULL OR rubric_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR rubric_sha256 = 'unverified'),  -- why-null: unknown for legacy judgments
  store_uri TEXT,  -- why-null: in progress
  claimed_by_session TEXT,  -- why-null: only claims
  claimed_utc TEXT CHECK (claimed_utc IS NULL OR claimed_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: only claims
  status TEXT NOT NULL CHECK (status IN ('in_progress', 'complete', 'partial', 'superseded', 'abandoned')),
  superseded_by_judgment_id TEXT REFERENCES judgment(judgment_id),  -- why-null: only superseded judgments
  producer_session TEXT,  -- why-null: unknown for legacy judgments
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (judgment_id)
);
CREATE INDEX idx_judgment_run ON judgment (run_id, judge_id);

-- Aggregate metrics per run × judgment × metric × threshold × computation; degeneration fractions mirror run_degeneration's `all`-scope rates.
CREATE TABLE run_metric (
  run_id TEXT NOT NULL REFERENCES run(run_id),
  judgment_id TEXT NOT NULL DEFAULT '',  -- '' for rule-scored metrics (FK by trigger otherwise).
  metric_id TEXT NOT NULL,
  threshold REAL NOT NULL DEFAULT -1,  -- -1 when the metric has no threshold.
  computation_id TEXT NOT NULL DEFAULT '',  -- '' for producer-filed values (FK by trigger otherwise) (F9).
  producer_metric_spelling TEXT,  -- why-null: only backfilled rows carry the producer's spelling
  value REAL,  -- why-null: disposition rows carry no value
  k INTEGER,  -- why-null: not every metric is a count
  n INTEGER,  -- why-null: not every metric has a denominator
  ci_lo REAL,  -- why-null: not every producer computed an interval
  ci_hi REAL,  -- why-null: not every producer computed an interval
  ci_method TEXT,  -- why-null: null when no interval
  frac_at_token_cap REAL,  -- why-null: filled from run_degeneration's all-scope rate where the producer computed it
  frac_degenerate_classifier REAL,  -- why-null: filled from run_degeneration's all-scope rate where the producer computed it
  frac_degenerate_contentless REAL,  -- why-null: filled from run_degeneration's all-scope rate where the producer computed it
  frac_degenerate_rep_ratio_loop REAL,  -- why-null: filled from run_degeneration's all-scope rate where the producer computed it
  frac_degenerate_zlib_collapse REAL,  -- why-null: filled from run_degeneration's all-scope rate where the producer computed it
  frac_degenerate_union5 REAL,  -- why-null: filled from run_degeneration's all-scope rate where the producer computed it
  frac_loop_first512 REAL,  -- why-null: filled from run_degeneration's all-scope rate where the producer computed it
  frac_defended_degenerate REAL,  -- why-null: filled from run_degeneration's all-scope rate where the producer computed it
  n_abstentions INTEGER,  -- why-null: not counted by every producer
  n_error_outcomes INTEGER,  -- why-null: not counted by every producer
  n_incomplete INTEGER,  -- why-null: not counted by every producer
  computed_by TEXT NOT NULL CHECK (computed_by IN ('producer', 'registry')),
  computed_utc TEXT CHECK (computed_utc IS NULL OR computed_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: unknown for legacy rows
  source_uri TEXT,  -- why-null: natively emitted rows are their own source
  source_producers_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(source_producers_json)),  -- Every producer file a multi-producer row was assembled from.
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (run_id, judgment_id, metric_id, threshold, computation_id),
  CONSTRAINT run_metric_metric_id_not_generic CHECK (metric_id NOT IN ('score', 'value', 'metric', 'result', 'accuracy', 'mean', 'count', 'total', 'number', 'frac', 'fraction', 'share', 'pct', 'percent', 'stat', 'statistic', 'measure', 'outcome', 'degenerate', 'degeneration', 'degeneracy', 'degen', 'loop', 'looping', 'loops', 'at_cap', 'capped', 'truncated', 'truncation', 'collapse', 'frac_degenerate', 'degenerate_rate', 'degenerate_frac', 'degenerate_fraction', 'loop_rate', 'frac_loop', 'loop_frac', 'at_cap_rate', 'frac_at_cap', 'at_cap_frac', 'at_cap_fraction', 'classifier', 'frac_classifier', 'classifier_rate', 'classifier_frac', 'classifier_share', 'degen_classifier_share', 'contentless', 'frac_contentless', 'contentless_rate', 'contentless_frac', 'contentless_share', 'degen_contentless_share', 'rep_ratio_loop', 'frac_rep_ratio_loop', 'rep_ratio_loop_rate', 'rep_ratio_loop_frac', 'rep_ratio_loop_share', 'degen_rep_ratio_loop_share', 'zlib_collapse', 'frac_zlib_collapse', 'zlib_collapse_rate', 'zlib_collapse_frac', 'zlib_collapse_share', 'degen_zlib_collapse_share', 'union5', 'frac_union5', 'union5_rate', 'union5_frac', 'union5_share', 'degen_union5_share', 'at_token_cap', 'frac_at_token_cap', 'at_token_cap_rate', 'at_token_cap_frac', 'at_token_cap_share', 'degen_at_token_cap_share', 'at_token_cap_retokenized', 'frac_at_token_cap_retokenized', 'at_token_cap_retokenized_rate', 'at_token_cap_retokenized_frac', 'at_token_cap_retokenized_share', 'degen_at_token_cap_retokenized_share', 'at_token_cap_finish_reason', 'frac_at_token_cap_finish_reason', 'at_token_cap_finish_reason_rate', 'at_token_cap_finish_reason_frac', 'at_token_cap_finish_reason_share', 'degen_at_token_cap_finish_reason_share', 'loop_first512', 'frac_loop_first512', 'loop_first512_rate', 'loop_first512_frac', 'loop_first512_share', 'degen_loop_first512_share', 'defended_degenerate', 'frac_defended_degenerate', 'defended_degenerate_rate', 'defended_degenerate_frac', 'defended_degenerate_share', 'degen_defended_degenerate_share', 'tail_loop', 'frac_tail_loop', 'tail_loop_rate', 'tail_loop_frac', 'tail_loop_share', 'degen_tail_loop_share', 'line_loop', 'frac_line_loop', 'line_loop_rate', 'line_loop_frac', 'line_loop_share', 'degen_line_loop_share', 'truncation_only', 'frac_truncation_only', 'truncation_only_rate', 'truncation_only_frac', 'truncation_only_share', 'degen_truncation_only_share', 'loop_without_cap', 'frac_loop_without_cap', 'loop_without_cap_rate', 'loop_without_cap_frac', 'loop_without_cap_share', 'degen_loop_without_cap_share', 'loop_or_at_cap', 'frac_loop_or_at_cap', 'loop_or_at_cap_rate', 'loop_or_at_cap_frac', 'loop_or_at_cap_share', 'degen_loop_or_at_cap_share', 'at_cap_share', 'loop_share', 'degenerate_share', 'degenerate_share_union5', 'at_cap_share_retokenized', 'at_cap_share_finish_reason', 'frac_degenerate_classifier', 'frac_degenerate_contentless', 'frac_degenerate_rep_ratio_loop', 'frac_degenerate_zlib_collapse', 'frac_degenerate_union5'))
);

-- Paired contrasts against an anchor run.
CREATE TABLE run_contrast (
  run_id TEXT NOT NULL REFERENCES run(run_id),
  anchor_run_id TEXT NOT NULL REFERENCES run(run_id),
  judgment_id TEXT NOT NULL DEFAULT '',
  metric_id TEXT NOT NULL,
  threshold REAL NOT NULL DEFAULT -1,
  computation_id TEXT NOT NULL DEFAULT '',
  anchor_judgment_id TEXT NOT NULL DEFAULT '',
  anchor_kind TEXT NOT NULL CHECK (anchor_kind IN ('same_standup_none', 'sibling_none', 'borrowed', 'full_dose')),
  delta REAL,  -- why-null: undefined when n_pairs is 0
  delta_lo REAL,  -- why-null: no interval computed
  delta_hi REAL,  -- why-null: no interval computed
  delta_p REAL,  -- why-null: no p-value computed
  delta_method TEXT NOT NULL,
  effect_size REAL,  -- why-null: no effect size computed
  effect_kind TEXT CHECK (effect_kind IN ('cohens_h', 'dz')),  -- why-null: null when effect_size is null
  n_pairs INTEGER NOT NULL,
  computed_by TEXT NOT NULL CHECK (computed_by IN ('producer', 'registry')),
  computed_utc TEXT CHECK (computed_utc IS NULL OR computed_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: unknown for legacy rows
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (run_id, anchor_run_id, judgment_id, metric_id, threshold, computation_id),
  CONSTRAINT run_contrast_metric_id_not_generic CHECK (metric_id NOT IN ('score', 'value', 'metric', 'result', 'accuracy', 'mean', 'count', 'total', 'number', 'frac', 'fraction', 'share', 'pct', 'percent', 'stat', 'statistic', 'measure', 'outcome', 'degenerate', 'degeneration', 'degeneracy', 'degen', 'loop', 'looping', 'loops', 'at_cap', 'capped', 'truncated', 'truncation', 'collapse', 'frac_degenerate', 'degenerate_rate', 'degenerate_frac', 'degenerate_fraction', 'loop_rate', 'frac_loop', 'loop_frac', 'at_cap_rate', 'frac_at_cap', 'at_cap_frac', 'at_cap_fraction', 'classifier', 'frac_classifier', 'classifier_rate', 'classifier_frac', 'classifier_share', 'degen_classifier_share', 'contentless', 'frac_contentless', 'contentless_rate', 'contentless_frac', 'contentless_share', 'degen_contentless_share', 'rep_ratio_loop', 'frac_rep_ratio_loop', 'rep_ratio_loop_rate', 'rep_ratio_loop_frac', 'rep_ratio_loop_share', 'degen_rep_ratio_loop_share', 'zlib_collapse', 'frac_zlib_collapse', 'zlib_collapse_rate', 'zlib_collapse_frac', 'zlib_collapse_share', 'degen_zlib_collapse_share', 'union5', 'frac_union5', 'union5_rate', 'union5_frac', 'union5_share', 'degen_union5_share', 'at_token_cap', 'frac_at_token_cap', 'at_token_cap_rate', 'at_token_cap_frac', 'at_token_cap_share', 'degen_at_token_cap_share', 'at_token_cap_retokenized', 'frac_at_token_cap_retokenized', 'at_token_cap_retokenized_rate', 'at_token_cap_retokenized_frac', 'at_token_cap_retokenized_share', 'degen_at_token_cap_retokenized_share', 'at_token_cap_finish_reason', 'frac_at_token_cap_finish_reason', 'at_token_cap_finish_reason_rate', 'at_token_cap_finish_reason_frac', 'at_token_cap_finish_reason_share', 'degen_at_token_cap_finish_reason_share', 'loop_first512', 'frac_loop_first512', 'loop_first512_rate', 'loop_first512_frac', 'loop_first512_share', 'degen_loop_first512_share', 'defended_degenerate', 'frac_defended_degenerate', 'defended_degenerate_rate', 'defended_degenerate_frac', 'defended_degenerate_share', 'degen_defended_degenerate_share', 'tail_loop', 'frac_tail_loop', 'tail_loop_rate', 'tail_loop_frac', 'tail_loop_share', 'degen_tail_loop_share', 'line_loop', 'frac_line_loop', 'line_loop_rate', 'line_loop_frac', 'line_loop_share', 'degen_line_loop_share', 'truncation_only', 'frac_truncation_only', 'truncation_only_rate', 'truncation_only_frac', 'truncation_only_share', 'degen_truncation_only_share', 'loop_without_cap', 'frac_loop_without_cap', 'loop_without_cap_rate', 'loop_without_cap_frac', 'loop_without_cap_share', 'degen_loop_without_cap_share', 'loop_or_at_cap', 'frac_loop_or_at_cap', 'loop_or_at_cap_rate', 'loop_or_at_cap_frac', 'loop_or_at_cap_share', 'degen_loop_or_at_cap_share', 'at_cap_share', 'loop_share', 'degenerate_share', 'degenerate_share_union5', 'at_cap_share_retokenized', 'at_cap_share_finish_reason', 'frac_degenerate_classifier', 'frac_degenerate_contentless', 'frac_degenerate_rep_ratio_loop', 'frac_degenerate_zlib_collapse', 'frac_degenerate_union5'))
);

-- Degeneration and truncation as COUNTS with their unit; never changes a run's state, status or paper flag. `measurement_state` says whether the row was measured. `v_run_degeneration_current` keeps one row per (run_id, judgment_id, measure, scope): native rows first, then a row carrying a number (`measured`) before every placeholder state, then the declared source priority, source_id and revision — a placeholder never hides a sibling provenance's number.
CREATE TABLE run_degeneration (
  run_id TEXT NOT NULL,
  judgment_id TEXT NOT NULL DEFAULT '',
  measure TEXT NOT NULL CHECK (measure IN ('classifier', 'contentless', 'rep_ratio_loop', 'zlib_collapse', 'union5', 'at_token_cap', 'at_token_cap_retokenized', 'at_token_cap_finish_reason', 'loop_first512', 'defended_degenerate', 'tail_loop', 'line_loop', 'truncation_only', 'loop_without_cap', 'loop_or_at_cap')),
  scope TEXT NOT NULL CHECK (scope IN ('all', 'defended_only', 'first_512_tokens', 'terminated_only')),
  measurement_state TEXT NOT NULL CHECK (measurement_state IN ('measured', 'not_measured', 'not_applicable', 'refused')),  -- measured | not_measured | not_applicable | refused; consumers branch on this, never on a NULL rate.
  numerator INTEGER,  -- why-null: NULL unless measurement_state = measured (table CHECK run_degeneration_measured_pairing)
  denominator INTEGER,  -- why-null: NULL unless measurement_state = measured (table CHECK)
  denominator_unit TEXT CHECK (denominator_unit IN ('items', 'draws', 'replies', 'turns', 'transcripts', 'scenarios')),  -- why-null: NULL unless measurement_state = measured (table CHECK)
  pooling_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(pooling_json)),
  aggregation TEXT NOT NULL CHECK (aggregation IN ('single_detector', 'union', 'max_single_detector', 'floor')),
  rate REAL,  -- why-null: NULL unless measurement_state = measured (table CHECK); undefined when the denominator is 0 is recorded as not_measured
  definition_version TEXT NOT NULL,
  threshold_params_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(threshold_params_json)),
  computed_by TEXT NOT NULL CHECK (computed_by IN ('producer', 'registry')),
  computed_utc TEXT CHECK (computed_utc IS NULL OR computed_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: unknown for legacy rows
  source_uri TEXT,  -- why-null: natively emitted rows are their own source
  notes TEXT,  -- why-null: free text
  source_revision_id TEXT NOT NULL DEFAULT '',  -- The source_revision that carries this row ('' for natively emitted rows; FK by trigger). Part of the key: rows of a pending or superseded revision coexist with the head's, invisible to every reader.
  written_utc INTEGER NOT NULL CHECK (written_utc >= 0),  -- Record written_utc as epoch milliseconds — stamp column 1.
  record_sha256 BLOB NOT NULL,  -- Record sha256 (32 bytes) — stamp column 2; (written_utc, record_sha256) is the row's order key.
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped.
  record_file_id INTEGER NOT NULL REFERENCES record_ingest(record_file_id),  -- The record file that produced the row (integer id; `v_item_pointer` renders the URI).
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest; derived, never allocated).
  PRIMARY KEY (run_id, judgment_id, measure, scope, source_revision_id),
  CONSTRAINT run_degeneration_measured_pairing CHECK ((measurement_state = 'measured' AND numerator IS NOT NULL AND denominator IS NOT NULL AND denominator_unit IS NOT NULL AND rate IS NOT NULL) OR (measurement_state <> 'measured' AND numerator IS NULL AND denominator IS NULL AND denominator_unit IS NULL AND rate IS NULL))
) WITHOUT ROWID;
CREATE INDEX idx_run_degeneration_revision ON run_degeneration (source_revision_id, record_file_id);

-- A file on disk (sha256, else sha256 of the URI) with its locations; text lives here by pointer, never in a row.
CREATE TABLE artifact (
  artifact_id TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('store_root', 'generations', 'judge_items', 'rows', 'object_weights', 'report', 'record', 'snapshot', 'log', 'completion', 'figure', 'page')),
  uri_primary TEXT NOT NULL,
  locations_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(locations_json)),
  bytes INTEGER,  -- why-null: unknown until verified
  created_utc TEXT CHECK (created_utc IS NULL OR created_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: unknown for legacy files
  verified_utc TEXT CHECK (verified_utc IS NULL OR verified_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: not yet verified against disk
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (artifact_id)
);

-- Per item × metric scores and labels (F10); text by pointer through item_flags. Keyed by revision too: read through `v_item_result_current` (or the same predicate), never raw.
CREATE TABLE item_result (
  run_id TEXT NOT NULL,
  item_id TEXT NOT NULL,
  metric_id TEXT NOT NULL,
  trial_index INTEGER NOT NULL DEFAULT 0,
  sample_index INTEGER NOT NULL DEFAULT 0,
  turn_index INTEGER NOT NULL DEFAULT -1,  -- -1 for single-turn items.
  judgment_id TEXT NOT NULL DEFAULT '',  -- '' for generation-time metrics (FK by trigger otherwise).
  value REAL,  -- why-null: label-only metrics carry no number
  label TEXT,  -- why-null: numeric-only metrics carry no label
  api_pool TEXT CHECK (api_pool IN ('lowprio', 'highprio', 'batch')),  -- why-null: rule-scored rows have no pool; legacy judged rows may not name one
  created_utc TEXT NOT NULL CHECK (created_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  judged_utc TEXT CHECK (judged_utc IS NULL OR judged_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: generation-time rows
  source_revision_id TEXT NOT NULL DEFAULT '',  -- The source_revision that carries this row ('' for natively emitted rows; FK by trigger). Part of the key: rows of a pending or superseded revision coexist with the head's, invisible to every reader.
  withdrawn_by_revision_id TEXT,  -- why-null: set when a later accepted revision no longer carries the item; bookkeeping — visibility is derived from the head revision
  written_utc INTEGER NOT NULL CHECK (written_utc >= 0),  -- Record written_utc as epoch milliseconds — stamp column 1.
  record_sha256 BLOB NOT NULL,  -- Record sha256 (32 bytes) — stamp column 2; (written_utc, record_sha256) is the row's order key.
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped.
  record_file_id INTEGER NOT NULL REFERENCES record_ingest(record_file_id),  -- The record file that produced the row (integer id; `v_item_pointer` renders the URI).
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest; derived, never allocated).
  PRIMARY KEY (run_id, item_id, metric_id, trial_index, sample_index, turn_index, judgment_id, source_revision_id)
) WITHOUT ROWID;
CREATE INDEX idx_item_result_run_judgment ON item_result (run_id, judgment_id);
CREATE INDEX idx_item_result_item ON item_result (item_id);
CREATE INDEX idx_item_result_withdrawn ON item_result (withdrawn_by_revision_id) WHERE withdrawn_by_revision_id IS NOT NULL;
CREATE INDEX idx_item_result_revision ON item_result (source_revision_id, record_file_id);

-- Per-item facts that do not vary by metric: truncation, degeneration flags, seeds and the generation / rationale pointers (F10). Keyed by revision too: read through `v_item_flags_current`.
CREATE TABLE item_flags (
  run_id TEXT NOT NULL,
  item_id TEXT NOT NULL,
  trial_index INTEGER NOT NULL DEFAULT 0,
  sample_index INTEGER NOT NULL DEFAULT 0,
  turn_index INTEGER NOT NULL DEFAULT -1,
  judgment_id TEXT NOT NULL DEFAULT '',
  at_token_cap INTEGER CHECK (at_token_cap IN (0, 1)),  -- why-null: unknown for legacy aggregates
  finish_reason TEXT,  -- why-null: unknown for legacy aggregates
  response_tokens INTEGER,  -- why-null: unknown for legacy aggregates
  response_chars INTEGER,  -- why-null: unknown for legacy aggregates
  degenerate_classifier INTEGER CHECK (degenerate_classifier IN (0, 1)),  -- why-null: not computed by every producer
  degenerate_contentless INTEGER CHECK (degenerate_contentless IN (0, 1)),  -- why-null: not computed by every producer
  degenerate_rep_ratio_loop INTEGER CHECK (degenerate_rep_ratio_loop IN (0, 1)),  -- why-null: not computed by every producer
  degenerate_zlib_collapse INTEGER CHECK (degenerate_zlib_collapse IN (0, 1)),  -- why-null: not computed by every producer
  degenerate_union5 INTEGER CHECK (degenerate_union5 IN (0, 1)),  -- why-null: not computed by every producer
  loop_first512 INTEGER CHECK (loop_first512 IN (0, 1)),  -- why-null: not computed by every producer
  rep_ratio REAL,  -- why-null: not computed by every producer
  zlib_ratio REAL,  -- why-null: not computed by every producer
  alnum_count INTEGER,  -- why-null: not computed by every producer
  tail_loop INTEGER CHECK (tail_loop IN (0, 1)),  -- why-null: not computed by every producer
  line_loop INTEGER CHECK (line_loop IN (0, 1)),  -- why-null: not computed by every producer
  decode_seed TEXT,  -- why-null: only per-item-seeded evals
  generation_artifact_id TEXT,  -- why-null: legacy aggregates have no per-item pointer
  generation_offset INTEGER,  -- why-null: null when generation_artifact_id is null
  rationale_artifact_id TEXT,  -- why-null: rule-scored and unjudged items
  rationale_offset INTEGER,  -- why-null: null when rationale_artifact_id is null
  source_revision_id TEXT NOT NULL DEFAULT '',  -- The source_revision that carries this row ('' for natively emitted rows; FK by trigger). Part of the key: rows of a pending or superseded revision coexist with the head's, invisible to every reader.
  written_utc INTEGER NOT NULL CHECK (written_utc >= 0),  -- Record written_utc as epoch milliseconds — stamp column 1.
  record_sha256 BLOB NOT NULL,  -- Record sha256 (32 bytes) — stamp column 2; (written_utc, record_sha256) is the row's order key.
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped.
  record_file_id INTEGER NOT NULL REFERENCES record_ingest(record_file_id),  -- The record file that produced the row (integer id; `v_item_pointer` renders the URI).
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest; derived, never allocated).
  PRIMARY KEY (run_id, item_id, trial_index, sample_index, turn_index, judgment_id, source_revision_id)
) WITHOUT ROWID;
CREATE INDEX idx_item_flags_revision ON item_flags (source_revision_id, record_file_id);

-- One declared paper comparison input of a round; instruments are matched per comparison, never globally.
CREATE TABLE roster_entry (
  roster_entry_id TEXT NOT NULL,
  round_id TEXT NOT NULL REFERENCES paper_round(round_id),
  comparison_id TEXT NOT NULL,
  model_id TEXT NOT NULL REFERENCES model(model_id),
  object_id TEXT REFERENCES object(object_id),  -- why-null: the object may be chosen by rule (object_selector_json; CHECK one of the two)
  object_selector_json TEXT CHECK (object_selector_json IS NULL OR json_valid(object_selector_json)),  -- why-null: null when object_id names the object (CHECK one of the two)
  eval_id TEXT NOT NULL REFERENCES eval(eval_id),
  instrument_id TEXT REFERENCES instrument(instrument_id),  -- why-null: the roster may select an instrument FAMILY (instrument_selector_json; C2; CHECK one of the two)
  instrument_selector_json TEXT CHECK (instrument_selector_json IS NULL OR json_valid(instrument_selector_json)),  -- why-null: null when instrument_id names the instrument (CHECK one of the two)
  judge_id TEXT REFERENCES judge(judge_id),  -- why-null: rule-scored comparisons have no judge; or the judge is chosen by rule (judge_selector_json)
  judge_selector_json TEXT CHECK (judge_selector_json IS NULL OR json_valid(judge_selector_json)),  -- why-null: null when judge_id names the judge or the comparison is rule-scored (C2)
  computation_id TEXT REFERENCES computation(computation_id),  -- why-null: raw producer values name no computation
  strength_rule TEXT NOT NULL CHECK (strength_rule = 'operating_point' OR strength_rule GLOB 'fixed:*' OR strength_rule GLOB 'ladder:*'),  -- `operating_point` | `fixed:<x>` | `ladder:<record_id>` (every strength level the record carries).
  source_citation TEXT NOT NULL,
  inferred INTEGER NOT NULL DEFAULT 0 CHECK (inferred IN (0, 1)),
  drawn INTEGER NOT NULL DEFAULT 1 CHECK (drawn IN (0, 1)),  -- 0 = required by the gap map but not drawn by the figure at the transcribed sha.
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (roster_entry_id),
  CONSTRAINT roster_entry_object_xor_selector CHECK ((object_id IS NULL) <> (object_selector_json IS NULL)),
  CONSTRAINT roster_entry_instrument_xor_selector CHECK ((instrument_id IS NULL) <> (instrument_selector_json IS NULL)),
  CONSTRAINT roster_entry_judge_not_both CHECK (NOT (judge_id IS NOT NULL AND judge_selector_json IS NOT NULL))
);
CREATE INDEX idx_roster_entry_key ON roster_entry (round_id, model_id, eval_id);

-- Why a roster key has no judged run (a source that has not run emits a disposition, never silence).
CREATE TABLE disposition (
  disposition_id TEXT NOT NULL,
  round_id TEXT NOT NULL REFERENCES paper_round(round_id),
  roster_entry_id TEXT REFERENCES roster_entry(roster_entry_id),  -- why-null: a disposition may cover a key with no roster entry yet
  comparison_id TEXT NOT NULL,
  model_id TEXT NOT NULL REFERENCES model(model_id),
  object_id TEXT REFERENCES object(object_id),  -- why-null: a disposition may cover every object of the key
  eval_id TEXT NOT NULL REFERENCES eval(eval_id),
  state TEXT NOT NULL CHECK (state IN ('pending', 'held', 'not_served', 'not_applicable', 'declined')),
  reason TEXT NOT NULL,
  source_ref TEXT NOT NULL,
  ruled_utc TEXT NOT NULL CHECK (ruled_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (disposition_id)
);

-- A published point-in-time snapshot (per-table Parquet + run-level SQLite), its ingest_seq and destinations.
CREATE TABLE snapshot (
  snapshot_id TEXT NOT NULL,
  head_ingest_seq INTEGER NOT NULL,  -- The index head (max ingest_seq) inside the frozen read transaction at build time.
  built_utc TEXT NOT NULL CHECK (built_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  sqlite_sha256 TEXT NOT NULL CHECK (sqlite_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),
  parquet_manifest_json TEXT NOT NULL CHECK (json_valid(parquet_manifest_json)),
  pushed_to_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(pushed_to_json)),
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (snapshot_id)
);

-- One run of the paper parity gate: the paper sha AND the sha256 of every input the pinned checkout read; the gate refuses when any input sha differs between its legacy and registry legs.
CREATE TABLE parity_gate (
  gate_id TEXT NOT NULL,
  paper_sha TEXT NOT NULL CHECK (paper_sha GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR paper_sha = 'unverified'),
  paper_checkout_uri TEXT,  -- why-null: a gate run from a bare sha records no checkout path
  input_shas_json TEXT NOT NULL CHECK (json_valid(input_shas_json)),  -- {input uri: sha256} of the r2 parquet / schema / sources and every record file the checkout read.
  registry_ingest_seq INTEGER NOT NULL,
  level TEXT NOT NULL CHECK (level IN ('L0', 'L1', 'L1b', 'L1c', 'L2')),
  result TEXT NOT NULL CHECK (result IN ('pass', 'fail', 'refused')),
  report_uri TEXT,  -- why-null: a refused gate may write no report
  run_utc TEXT NOT NULL CHECK (run_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (gate_id)
);

-- One accepted (or refused) read of a legacy source by an adapter; `v_paper_long` reads only the latest accepted revision per source (S4).
CREATE TABLE source_revision (
  revision_id TEXT NOT NULL,  -- sha16 of the sorted input shas.
  source_id TEXT NOT NULL,
  adapter TEXT NOT NULL,
  observed_utc TEXT NOT NULL CHECK (observed_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  inputs_json TEXT NOT NULL CHECK (json_valid(inputs_json)),  -- {uri: sha256} of every input read.
  accepted INTEGER NOT NULL CHECK (accepted IN (0, 1)),
  refusal TEXT,  -- why-null: accepted revisions have no refusal
  superseded_by_revision_id TEXT,  -- why-null: the latest revision of a source is not superseded
  priority INTEGER NOT NULL DEFAULT 0,  -- The adapter's declared source priority: among the visible provenances of one measurement key a native row comes first, then the higher priority, then the lexically smaller source_id, then revision_id.
  reclaimed INTEGER NOT NULL DEFAULT 0 CHECK (reclaimed IN (0, 1)),  -- 1 once the reclaim pass has marked every row of this superseded revision the successor no longer carries; reset when the chain moves.
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (revision_id)
);
CREATE INDEX idx_source_revision_source ON source_revision (source_id, observed_utc);

-- Membership of a RUN-SCALE key in a source revision (item membership is two columns on item_result).
CREATE TABLE observation (
  source_id TEXT NOT NULL,
  revision_id TEXT NOT NULL REFERENCES source_revision(revision_id),
  observation_key TEXT NOT NULL,  -- Canonical JSON of the natural key.
  table_name TEXT NOT NULL,
  current INTEGER NOT NULL DEFAULT 1 CHECK (current IN (0, 1)),
  withdrawn_by_revision_id TEXT,  -- why-null: set when a later accepted revision no longer carries the key
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (source_id, revision_id, observation_key)
);

-- A key present in the previous accepted revision and absent from the new one (a real shrink, visible to the paper build's shrink refusal).
CREATE TABLE withdrawal (
  source_id TEXT NOT NULL,
  observation_key TEXT NOT NULL,
  from_revision_id TEXT NOT NULL,
  to_revision_id TEXT NOT NULL REFERENCES source_revision(revision_id),
  table_name TEXT NOT NULL,
  reason TEXT NOT NULL CHECK (reason IN ('removed_measurement', 'removed_items', 'input_vanished')),
  item_keys_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(item_keys_json)),
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (source_id, observation_key, to_revision_id)
);

-- Per-input watermark of the incremental adapter pass (F5).
CREATE TABLE source_watermark (
  source_id TEXT NOT NULL,
  input_uri TEXT NOT NULL,
  sha256 TEXT NOT NULL CHECK (sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' OR sha256 = 'unverified'),
  size INTEGER NOT NULL,
  mtime_utc TEXT NOT NULL CHECK (mtime_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  observed_utc TEXT NOT NULL CHECK (observed_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  adapter TEXT NOT NULL,
  records_written INTEGER NOT NULL DEFAULT 0,
  last_error TEXT,  -- why-null: the last read succeeded
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (source_id, input_uri)
);

-- What a source file names NOW under a JSON path (the faithful `declaration_root_state` port, F8); ruling expiry is evaluated against it.
CREATE TABLE source_state (
  source_id TEXT NOT NULL,
  input_uri TEXT NOT NULL,
  json_path TEXT NOT NULL,
  found INTEGER NOT NULL CHECK (found IN (0, 1)),
  path_resolves INTEGER NOT NULL CHECK (path_resolves IN (0, 1)),
  current_members_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(current_members_json)),
  observed_utc TEXT NOT NULL CHECK (observed_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  input_sha256 TEXT CHECK (input_sha256 IS NULL OR input_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),  -- why-null: null when found = 0
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (source_id, input_uri, json_path)
);

-- What ONE adapter read of ONE source found, filed under every paper source string (`lane_source_legacy`) the adapter covers — the registry-side half of the paper's status contract. Written by the adapter runner after each accepted read, once per read (the revision tag keys the row), so the history of a source's reads is the table and the head read is `v_source_status_current`. `extra_json` carries the adapter's FACTS (the producer records it read and reduced: ruled operating points, dose tables, the record's roster, engines); the paper's guards DECIDE on them in the reader, the registry only carries the evidence. `v_source_status` reduces the head reads to one row per (`lane_source_legacy`, adapter) and folds in the LATEST revision of each source, accepted or refused, so a refused re-read is visible there (`ok = 0`, `extra_json.refuse`) instead of hidden behind the accepted head it leaves current.
CREATE TABLE source_status (
  lane_source_legacy TEXT NOT NULL,  -- The paper's source string this row reports on (`covers_sources`); the join key to `v_paper_long.lane_source_legacy`.
  adapter TEXT NOT NULL,  -- The adapter that read the source (`source_revision.adapter`).
  source_id TEXT NOT NULL,  -- `<adapter>:<comparison group>`, the source this read was of (an adapter with several groups files one row per group).
  owner TEXT NOT NULL,  -- The producing session the adapter names for the source (`registry` when it names none).
  where_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(where_json)),  -- JSON list of the input uris the read covered (`source_revision.inputs_json` keys).
  ok INTEGER NOT NULL CHECK (ok IN (0, 1)),  -- 1 when the read was accepted with nothing refused; 0 when the adapter recorded a refusal it could carry on past.
  detail TEXT NOT NULL DEFAULT '',  -- One line for the gap map: what was read, how many records / measured keys / dispositions, what was refused.
  cells_measured INTEGER NOT NULL DEFAULT 0 CHECK (cells_measured >= 0),  -- Distinct (model, object, eval) keys the read measured (a `run_metric` carrying a value).
  observed_utc TEXT NOT NULL CHECK (observed_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- When the adapter read the source (the pass's `now`).
  source_revision_id TEXT NOT NULL DEFAULT '',  -- The source_revision that carries this row ('' for natively emitted rows; FK by trigger). Part of the key: rows of a pending or superseded revision coexist with the head's, invisible to every reader.
  written_utc INTEGER NOT NULL CHECK (written_utc >= 0),  -- Record written_utc as epoch milliseconds — stamp column 1.
  record_sha256 BLOB NOT NULL,  -- Record sha256 (32 bytes) — stamp column 2; (written_utc, record_sha256) is the row's order key.
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped.
  record_file_id INTEGER NOT NULL REFERENCES record_ingest(record_file_id),  -- The record file that produced the row (integer id; `v_item_pointer` renders the URI).
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest; derived, never allocated).
  PRIMARY KEY (lane_source_legacy, adapter, source_id, source_revision_id)
) WITHOUT ROWID;
CREATE INDEX idx_source_status_revision ON source_status (source_revision_id, record_file_id);

-- Per-destination acknowledgement of the record-log fan-out (F2).
CREATE TABLE mirror_ack (
  destination TEXT NOT NULL CHECK (destination IN ('cluster_a', 'cluster_b', 'modal')),
  acked_through_seq INTEGER NOT NULL,
  manifest_name TEXT NOT NULL,
  file_count INTEGER NOT NULL,
  bytes INTEGER NOT NULL,
  checksums_sha256 TEXT NOT NULL CHECK (checksums_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),
  acked_utc TEXT NOT NULL CHECK (acked_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  last_error TEXT,  -- why-null: the last sync succeeded
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (destination)
);

-- The harvester's own fact of a record file's FIRST live fold: the arrival_utc that orders the file in the ledger (record_ingest), written into the log as a record so a rebuild reproduces ingest_seq exactly. Emitted once per file whose arrival differs from its first_written_utc (the replay's fallback); never for the harvester's own files under records/harvester/, whose stamp is their arrival.
CREATE TABLE file_arrival (
  file_uri TEXT NOT NULL,  -- Root-relative LOGICAL path of the file that arrived (record_ingest.file_uri).
  file_sha256 TEXT NOT NULL CHECK (file_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),  -- The logical sha the file arrived with.
  arrival_utc TEXT NOT NULL CHECK (arrival_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- The live registry's clock at the file's first fold — record_ingest.arrival_utc, verbatim.
  field_versions_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(field_versions_json)),  -- {column: [written_utc, record_sha256] of the record that last set it} — the FULL order key (S2).
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),  -- Unknown record fields, never dropped (Fixed decision 13).
  record_uri TEXT NOT NULL,  -- The record file (logical path) that produced the current row.
  ingest_seq INTEGER NOT NULL,  -- The producing FILE's rank in the ledger's arrival order (record_ingest: arrival_utc, then first_written_utc, sha, uri); derived, never allocated — every row above a head a reader has seen is new to it.
  PRIMARY KEY (file_uri)
);

-- Replayable FILE-scale ledger (spec: every file's sha and ingest_seq): ingest_seq is the dense rank of the file in ARRIVAL order — (arrival_utc, first_written_utc, logical sha256, uri) over the whole log — so a file the live registry folds is always head + 1 and every row above a head a reader has seen is new to it; every row of the index carries its file's rank. A rebuild reproduces the order from the file_arrival facts in the log (a file with none takes arrival_utc = first_written_utc). Per-record dedupe is the row_history event key / the item order key, not this table.
CREATE TABLE record_ingest (
  file_uri TEXT NOT NULL,  -- Root-relative LOGICAL path (no .gz).
  record_file_id INTEGER NOT NULL,  -- First 63 bits of sha256(file_uri): the arrival-independent integer id item rows point at.
  file_sha256 TEXT NOT NULL CHECK (file_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),  -- sha256 of the DECOMPRESSED bytes (two files may share it; each is its own ledger row).
  first_written_utc TEXT NOT NULL CHECK (first_written_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- The smallest written_utc among the file's accepted records — the tie-break after arrival_utc, and the arrival of a file the live registry never folded.
  arrival_utc TEXT NOT NULL CHECK (arrival_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- THE ordering stamp: the live registry's clock at the file's FIRST fold, strictly after the head's (max(cycle clock, head + 1 ms)); kept for the file's life (a re-read or re-keyed file keeps it). A harvester-originated file (records/harvester/) and a file a replay finds no file_arrival fact for take their first_written_utc.
  n_records INTEGER NOT NULL,
  ingest_seq INTEGER NOT NULL,
  PRIMARY KEY (file_uri),
  UNIQUE (record_file_id),
  UNIQUE (ingest_seq)
);
CREATE INDEX idx_record_ingest_sha ON record_ingest (file_sha256);
CREATE INDEX idx_record_ingest_order ON record_ingest (arrival_utc, first_written_utc, file_sha256, file_uri);

-- Arrival audit per record file (arrival-order dependent; excluded from rebuild equality).
CREATE TABLE record_delivery (
  file_uri TEXT NOT NULL,
  file_sha256 TEXT NOT NULL CHECK (file_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),
  arrived_utc TEXT NOT NULL CHECK (arrived_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  ingested_utc TEXT CHECK (ingested_utc IS NULL OR ingested_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: not yet ingested
  status TEXT NOT NULL CHECK (status IN ('ok', 'refused', 'duplicate', 'blocked', 'partial', 'conflict')),
  refusal_reason TEXT,  -- why-null: only refused / conflict files
  producer_script TEXT,  -- why-null: unreadable envelope
  producer_session TEXT,  -- why-null: producers outside a session
  schema_version INTEGER,  -- why-null: unreadable envelope
  record_type_counts_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(record_type_counts_json)),
  n_records INTEGER NOT NULL DEFAULT 0,
  n_ok INTEGER NOT NULL DEFAULT 0,
  n_refused INTEGER NOT NULL DEFAULT 0,
  n_blocked INTEGER NOT NULL DEFAULT 0,
  n_duplicate INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (file_uri)
);

-- Malformed records, refused with the field and reason; never silently skipped (listed on the status page).
CREATE TABLE record_refusal (
  record_sha256 TEXT NOT NULL CHECK (record_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),
  record_uri TEXT NOT NULL,
  record_type TEXT,  -- why-null: an envelope without a readable type
  field TEXT,  -- why-null: an envelope-level refusal names no field
  reason TEXT NOT NULL,
  refused_utc TEXT NOT NULL CHECK (refused_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  PRIMARY KEY (record_sha256)
);

-- File-scale index: one row per record file per run it mentions (the `registry history` fold for item-scale keys reads only these files).
CREATE TABLE record_run_index (
  run_id TEXT NOT NULL,
  record_uri TEXT NOT NULL,
  PRIMARY KEY (run_id, record_uri)
);

-- Well-formed records whose parent row is not yet ingested (F4); re-evaluated every cycle, never dropped. `stale` after 7 days, or at once when the record belongs to a pending revision whose source has since accepted a later one (`extra_json.superseded_by` names it) — no longer pending work.
CREATE TABLE blocked_records (
  record_sha256 TEXT NOT NULL CHECK (record_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),
  record_uri TEXT NOT NULL,
  record_type TEXT NOT NULL CHECK (record_type IN ('run', 'run_patch', 'run_state', 'run_metric', 'run_contrast', 'item_result', 'item_flags', 'run_degeneration', 'judgment', 'object', 'artifact', 'model', 'eval', 'item_set', 'instrument', 'judge', 'si_text', 'fit_search', 'fit_trial', 'paper_round', 'roster_entry', 'ruling', 'decode_policy', 'sampling_mode_policy', 'computation', 'disposition', 'snapshot', 'parity_gate', 'run_ingest', 'ruling_state', 'source_watermark', 'source_state', 'source_revision', 'observation', 'withdrawal', 'mirror_ack', 'file_arrival', 'source_status')),
  missing_parent_table TEXT NOT NULL,
  missing_parent_id TEXT NOT NULL,
  first_seen_utc TEXT NOT NULL CHECK (first_seen_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  last_checked_utc TEXT NOT NULL CHECK (last_checked_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  attempts INTEGER NOT NULL DEFAULT 1,
  stale INTEGER NOT NULL DEFAULT 0 CHECK (stale IN (0, 1)),
  extra_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),
  PRIMARY KEY (record_sha256)
);

-- Every event of a RUN-SCALE natural key with the folded state after it (derived; identical live and on replay). Item-scale keys keep their history in the record log.
CREATE TABLE row_history (
  table_name TEXT NOT NULL CHECK (table_name IN ('paper_round', 'model', 'si_text', 'fit_search', 'fit_trial', 'eval', 'item_set', 'judge', 'instrument', 'decode_policy', 'sampling_mode_policy', 'computation', 'ruling', 'ruling_state', 'object', 'run', 'run_state_event', 'judgment', 'run_metric', 'run_contrast', 'artifact', 'roster_entry', 'disposition', 'snapshot', 'parity_gate', 'source_revision', 'observation', 'withdrawal', 'source_watermark', 'source_state', 'mirror_ack', 'file_arrival')),
  natural_key_json TEXT NOT NULL CHECK (json_valid(natural_key_json)),
  written_utc TEXT NOT NULL CHECK (written_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  record_sha256 TEXT NOT NULL CHECK (record_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),
  record_type TEXT NOT NULL CHECK (record_type IN ('run', 'run_patch', 'run_state', 'run_metric', 'run_contrast', 'item_result', 'item_flags', 'run_degeneration', 'judgment', 'object', 'artifact', 'model', 'eval', 'item_set', 'instrument', 'judge', 'si_text', 'fit_search', 'fit_trial', 'paper_round', 'roster_entry', 'ruling', 'decode_policy', 'sampling_mode_policy', 'computation', 'disposition', 'snapshot', 'parity_gate', 'run_ingest', 'ruling_state', 'source_watermark', 'source_state', 'source_revision', 'observation', 'withdrawal', 'mirror_ack', 'file_arrival', 'source_status')),
  record_uri TEXT NOT NULL,
  payload_json TEXT NOT NULL CHECK (json_valid(payload_json)),  -- The effect this event has on the key's row.
  folded_state_json TEXT NOT NULL CHECK (json_valid(folded_state_json)),  -- The row after folding every event up to and including this one.
  PRIMARY KEY (table_name, natural_key_json, written_utc, record_sha256)
);

-- A revision's RUN-SCALE constituents (few), staged as records; validated and folded by the activation transaction.
CREATE TABLE revision_staging_record (
  revision_id TEXT NOT NULL,
  file_uri TEXT NOT NULL,
  line INTEGER NOT NULL,
  record_sha256 TEXT NOT NULL CHECK (record_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),
  written_utc TEXT NOT NULL CHECK (written_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  record_json TEXT NOT NULL CHECK (json_valid(record_json)),  -- The record, canonical JSON.
  PRIMARY KEY (revision_id, file_uri, line)
) WITHOUT ROWID;

-- One row per COMPLETELY staged constituent file of a revision: its verified sha, counts and envelope, so a held revision activates later without re-reading it.
CREATE TABLE revision_staging_file (
  revision_id TEXT NOT NULL,
  file_uri TEXT NOT NULL,
  file_sha256 TEXT NOT NULL CHECK (file_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),
  n_records INTEGER NOT NULL,
  first_written_utc TEXT CHECK (first_written_utc IS NULL OR first_written_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),  -- why-null: a file with no well-formed record has no first key
  counts_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(counts_json)),  -- {ok, refused, blocked, duplicate} of the file's item rows at staging.
  type_counts_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(type_counts_json)),
  producer_script TEXT,  -- why-null: unreadable envelope
  producer_session TEXT,  -- why-null: producers outside a session
  schema_version INTEGER,  -- why-null: unreadable envelope
  stat_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(stat_json)),  -- (size, mtime_ns, inode) taken before the file was read (the F12 sidecar entry).
  staged_utc TEXT NOT NULL CHECK (staged_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  PRIMARY KEY (revision_id, file_uri)
) WITHOUT ROWID;

-- Resumable progress of a plain file written across several transactions: the records already committed, so a restart resumes after them and applies every record once; deleted when the file's delivery row is written.
CREATE TABLE record_cursor (
  file_uri TEXT NOT NULL,
  file_sha256 TEXT NOT NULL CHECK (file_sha256 GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),  -- The discovery sha the progress belongs to; a file whose sha moved starts over.
  records_done INTEGER NOT NULL,
  counts_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(counts_json)),  -- Accumulated {counts, type_counts, n_refused} of the committed windows.
  updated_utc TEXT NOT NULL CHECK (updated_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  PRIMARY KEY (file_uri)
) WITHOUT ROWID;

-- ==================================================================== triggers
CREATE TRIGGER trg_run_judged_requires_judgment_ins BEFORE INSERT ON run
WHEN NEW.lifecycle_state = 'judged' AND NOT EXISTS (SELECT 1 FROM judgment WHERE run_id = NEW.run_id)
BEGIN
  SELECT RAISE(ABORT, 'run.lifecycle_state=judged requires a judgment row for this run_id');
END;
CREATE TRIGGER trg_run_judged_requires_judgment_upd BEFORE UPDATE OF lifecycle_state ON run
WHEN NEW.lifecycle_state = 'judged' AND NOT EXISTS (SELECT 1 FROM judgment WHERE run_id = NEW.run_id)
BEGIN
  SELECT RAISE(ABORT, 'run.lifecycle_state=judged requires a judgment row for this run_id');
END;
CREATE TRIGGER trg_run_state_utc_ins BEFORE INSERT ON run
WHEN (NEW.lifecycle_state = 'queued' AND (NEW.queued_utc IS NULL))
  OR (NEW.lifecycle_state = 'running' AND (NEW.queued_utc IS NULL OR NEW.started_utc IS NULL))
  OR (NEW.lifecycle_state = 'generated' AND (NEW.queued_utc IS NULL OR NEW.started_utc IS NULL OR NEW.generated_utc IS NULL))
  OR (NEW.lifecycle_state = 'judged' AND (NEW.queued_utc IS NULL OR NEW.started_utc IS NULL OR NEW.generated_utc IS NULL OR NEW.judged_utc IS NULL))
  OR (NEW.lifecycle_state = 'ingested' AND (NEW.queued_utc IS NULL OR NEW.started_utc IS NULL OR NEW.generated_utc IS NULL OR NEW.judged_utc IS NULL OR NEW.ingested_utc IS NULL))
  OR (NEW.lifecycle_state = 'judging' AND (NEW.queued_utc IS NULL OR NEW.started_utc IS NULL OR NEW.generated_utc IS NULL))
  OR (NEW.lifecycle_state IN ('failed','cancelled') AND (NEW.queued_utc IS NULL OR NEW.finished_utc IS NULL))
  OR (NEW.lifecycle_state IN ('superseded','withdrawn') AND NEW.queued_utc IS NULL)
BEGIN
  SELECT RAISE(ABORT, 'run: every *_utc of a reached lifecycle state must be non-null (trg_run_state_utc)');
END;
CREATE TRIGGER trg_run_state_utc_upd BEFORE UPDATE ON run
WHEN (NEW.lifecycle_state = 'queued' AND (NEW.queued_utc IS NULL))
  OR (NEW.lifecycle_state = 'running' AND (NEW.queued_utc IS NULL OR NEW.started_utc IS NULL))
  OR (NEW.lifecycle_state = 'generated' AND (NEW.queued_utc IS NULL OR NEW.started_utc IS NULL OR NEW.generated_utc IS NULL))
  OR (NEW.lifecycle_state = 'judged' AND (NEW.queued_utc IS NULL OR NEW.started_utc IS NULL OR NEW.generated_utc IS NULL OR NEW.judged_utc IS NULL))
  OR (NEW.lifecycle_state = 'ingested' AND (NEW.queued_utc IS NULL OR NEW.started_utc IS NULL OR NEW.generated_utc IS NULL OR NEW.judged_utc IS NULL OR NEW.ingested_utc IS NULL))
  OR (NEW.lifecycle_state = 'judging' AND (NEW.queued_utc IS NULL OR NEW.started_utc IS NULL OR NEW.generated_utc IS NULL))
  OR (NEW.lifecycle_state IN ('failed','cancelled') AND (NEW.queued_utc IS NULL OR NEW.finished_utc IS NULL))
  OR (NEW.lifecycle_state IN ('superseded','withdrawn') AND NEW.queued_utc IS NULL)
BEGIN
  SELECT RAISE(ABORT, 'run: every *_utc of a reached lifecycle state must be non-null (trg_run_state_utc)');
END;
CREATE TRIGGER trg_run_metric_judgment_id_fk_ins BEFORE INSERT ON run_metric
WHEN NEW.judgment_id <> '' AND NOT EXISTS (SELECT 1 FROM judgment WHERE judgment_id = NEW.judgment_id)
BEGIN
  SELECT RAISE(ABORT, 'run_metric.judgment_id names no judgment.judgment_id (sentinel-column FK)');
END;
CREATE TRIGGER trg_run_metric_judgment_id_fk_upd BEFORE UPDATE OF judgment_id ON run_metric
WHEN NEW.judgment_id <> '' AND NOT EXISTS (SELECT 1 FROM judgment WHERE judgment_id = NEW.judgment_id)
