CREATE TRIGGER trg_item_result_source_revision_id_fk_ins BEFORE INSERT ON item_result
WHEN NEW.source_revision_id <> '' AND NOT EXISTS (SELECT 1 FROM source_revision WHERE revision_id = NEW.source_revision_id)
BEGIN
  SELECT RAISE(ABORT, 'item_result.source_revision_id names no source_revision.revision_id (sentinel-column FK)');
END;
CREATE TRIGGER trg_item_result_source_revision_id_fk_upd BEFORE UPDATE OF source_revision_id ON item_result
WHEN NEW.source_revision_id <> '' AND NOT EXISTS (SELECT 1 FROM source_revision WHERE revision_id = NEW.source_revision_id)
BEGIN
  SELECT RAISE(ABORT, 'item_result.source_revision_id names no source_revision.revision_id (sentinel-column FK)');
END;
