WHEN (NEW.source_revision_id = '' OR EXISTS (SELECT 1 FROM source_revision sr_v WHERE sr_v.revision_id = NEW.source_revision_id AND sr_v.accepted = 1)) AND NOT EXISTS (SELECT 1 FROM run WHERE run_id = NEW.run_id)
