       MAX(CASE WHEN measure = 'union5' AND scope = 'terminated_only' THEN denominator_unit END) AS union5__terminated_only_unit,
       MAX(CASE WHEN measure = 'union5' AND scope = 'terminated_only' THEN measurement_state END) AS union5__terminated_only_state,
       MAX(CASE WHEN measure = 'at_token_cap' AND scope = 'all' THEN rate END) AS at_token_cap__all_rate,
