       MAX(CASE WHEN measure = 'at_token_cap' AND scope = 'defended_only' THEN rate END) AS at_token_cap__defended_only_rate,
       MAX(CASE WHEN measure = 'at_token_cap' AND scope = 'defended_only' THEN numerator END) AS at_token_cap__defended_only_num,
       MAX(CASE WHEN measure = 'at_token_cap' AND scope = 'defended_only' THEN denominator END) AS at_token_cap__defended_only_den,
       MAX(CASE WHEN measure = 'at_token_cap' AND scope = 'defended_only' THEN denominator_unit END) AS at_token_cap__defended_only_unit,
       MAX(CASE WHEN measure = 'at_token_cap' AND scope = 'defended_only' THEN measurement_state END) AS at_token_cap__defended_only_state,
       MAX(CASE WHEN measure = 'at_token_cap' AND scope = 'first_512_tokens' THEN rate END) AS at_token_cap__first_512_tokens_rate,
       MAX(CASE WHEN measure = 'at_token_cap' AND scope = 'first_512_tokens' THEN numerator END) AS at_token_cap__first_512_tokens_num,
       MAX(CASE WHEN measure = 'at_token_cap' AND scope = 'first_512_tokens' THEN denominator END) AS at_token_cap__first_512_tokens_den,
       MAX(CASE WHEN measure = 'at_token_cap' AND scope = 'first_512_tokens' THEN denominator_unit END) AS at_token_cap__first_512_tokens_unit,
       MAX(CASE WHEN measure = 'at_token_cap' AND scope = 'first_512_tokens' THEN measurement_state END) AS at_token_cap__first_512_tokens_state,
       MAX(CASE WHEN measure = 'at_token_cap' AND scope = 'terminated_only' THEN rate END) AS at_token_cap__terminated_only_rate,
       MAX(CASE WHEN measure = 'at_token_cap' AND scope = 'terminated_only' THEN numerator END) AS at_token_cap__terminated_only_num,
       MAX(CASE WHEN measure = 'at_token_cap' AND scope = 'terminated_only' THEN denominator END) AS at_token_cap__terminated_only_den,
       MAX(CASE WHEN measure = 'at_token_cap' AND scope = 'terminated_only' THEN denominator_unit END) AS at_token_cap__terminated_only_unit,
       MAX(CASE WHEN measure = 'at_token_cap' AND scope = 'terminated_only' THEN measurement_state END) AS at_token_cap__terminated_only_state,
       MAX(CASE WHEN measure = 'at_token_cap_retokenized' AND scope = 'all' THEN rate END) AS at_token_cap_retokenized__all_rate,
       MAX(CASE WHEN measure = 'at_token_cap_retokenized' AND scope = 'all' THEN numerator END) AS at_token_cap_retokenized__all_num,
       MAX(CASE WHEN measure = 'at_token_cap_retokenized' AND scope = 'all' THEN denominator END) AS at_token_cap_retokenized__all_den,
       MAX(CASE WHEN measure = 'at_token_cap_retokenized' AND scope = 'all' THEN denominator_unit END) AS at_token_cap_retokenized__all_unit,
       MAX(CASE WHEN measure = 'at_token_cap_retokenized' AND scope = 'all' THEN measurement_state END) AS at_token_cap_retokenized__all_state,
       MAX(CASE WHEN measure = 'at_token_cap_retokenized' AND scope = 'defended_only' THEN rate END) AS at_token_cap_retokenized__defended_only_rate,
       MAX(CASE WHEN measure = 'at_token_cap_retokenized' AND scope = 'defended_only' THEN numerator END) AS at_token_cap_retokenized__defended_only_num,
